re={truefalse:1,match:1,quiz:2,reverse:2,listen:2,clue:3,scramble:3,recall:4},se=1;function B(a,t,s){return s?Math.ceil(re[a]*(1+t*.25)):se}function xe(a,t,s,r){if(!r)return{cleared:0,clean:0,total:0};const o=a==="boss"?20+t*5:5+t*2,m=s?5:0;return{cleared:o,clean:m,total:o+m}}function Ie(a,t,s){return t>0&&a/t>=s.pass}function Te(a,t){return a.reduce((s,r)=>r.kind==="match"?s+r.pairs.length*B("match",r.tierIndex,t):s+B(r.kind,r.tierIndex,t),0)}const e=(a,t,s)=>({en:a,pt:t,zh:s}),F=(a,t,s)=>a&&t&&s?{why:e(a,t,s)}:{},c=a=>a.map(([t,s,r,o,m,u,d,h,q])=>({term:t,roman:s||void 0,meaning:e(r,o,m),...F(u,d,h),...q})),v=a=>a.map(([t,s,r,o,m,u,d,h,q])=>({term:e(t,s,r),meaning:e(o,m,u),...F(d,h,q)})),ne=a=>a.map(([t,s,r,o,m,u,d])=>({term:t,meaning:e(s,r,o),mono:!0,...F(m,u,d)})),ie=[{id:"ai-how",name:e("What is really going on","O que está acontecendo de verdade","它到底在干什么"),intro:e("Floor 0: it predicts likely next words — no fact database, no memory beyond what it can see now. Prompt tricks wait until that footing is solid.","Andar 0: ele prevê as próximas palavras mais prováveis — sem banco de fatos, sem memória além do que está vendo. Truque de prompt espera essa base.","第0层：它在预测下一个可能的词——没有事实库，记不住眼前之外的东西。提示词花招等这个地基稳了再说。"),quest:e("Ask any AI about something you know very well, and count its mistakes. Then log it with PLAY.","Pergunte a uma IA sobre algo que você conhece muito bem e conte os erros dela. Depois registre no JOGAR.","问 AI 一件你非常了解的事，数数它错了几处。然后用「实战」记下来。"),pack:{id:"ai-how",items:v([["Token","Token","词元","The small chunk of text a model reads and writes; usage is counted in these","O pedacinho de texto que o modelo lê e escreve; o uso é contado nisso","模型读写文字的小单位；用量按它计算","A long chat costs more per message, because the whole history gets read again.","Conversa longa custa mais por mensagem, porque o histórico inteiro é lido de novo.","聊得越久，每条消息越贵，因为整段历史都要重读一遍。"],["Context window","Janela de contexto","上下文窗口","Everything the model can see at once","Tudo o que o modelo consegue ver de uma vez","模型一次能看到的全部内容",'What falls outside it is gone, which is why very long chats "forget" how they started.','O que fica de fora some, e é por isso que conversas muito longas "esquecem" o começo.',"窗口之外的内容就没了，所以很长的对话会“忘记”开头。"],["Hallucination","Alucinação","幻觉","A confident answer that is simply made up","Uma resposta confiante que é pura invenção","说得很肯定，其实是编的","It predicts likely words, and likely is not the same as true.","Ele prevê palavras prováveis, e provável não é o mesmo que verdadeiro.","它预测的是“可能的词”，而可能不等于真实。"],["Knowledge cutoff","Data de corte","知识截止日期","The date its training data ends","A data em que os dados de treino terminam","训练数据截止的日期","Ask about last week and, without a search tool, it may just guess.","Pergunte sobre a semana passada e, sem ferramenta de busca, ele pode só chutar.","问上周的事，如果没有搜索工具，它可能只是在猜。"],["Temperature","Temperatura","温度","A setting for how much randomness goes into its word choice","Um ajuste de quanta aleatoriedade entra na escolha das palavras","控制选词随机程度的设置","Low for facts and code, higher for brainstorming.","Baixa para fatos e código, mais alta para ter ideias.","查事实、写代码时调低，头脑风暴时调高。"],["System prompt","Prompt de sistema","系统提示词","Standing instructions that shape every reply","Instruções fixas que moldam toda resposta","影响每次回复的固定指令","Custom instructions and rules files work this way: set once, applied always.","Instruções personalizadas e arquivos de regras funcionam assim: define uma vez, vale sempre.","自定义指令和规则文件就是这样：设一次，一直生效。"],["Language model","Modelo de linguagem","语言模型","A program trained on huge amounts of text to predict the next words","Um programa treinado com muito texto para prever as próximas palavras","用海量文本训练、用来预测下一个词的程序","It learned patterns. It is not looking anything up unless it has a tool for that.","Ele aprendeu padrões. Não está consultando nada, a não ser que tenha uma ferramenta para isso.","它学的是规律。除非有工具，否则它并没有在查资料。"],["Tool call","Chamada de ferramenta","工具调用","When the model asks a program to search, calculate or run code","Quando o modelo pede a um programa para buscar, calcular ou rodar código","模型请程序去搜索、计算或运行代码","With tools it can check things. Without them it only has what it absorbed in training.","Com ferramentas ele consegue checar. Sem elas, só tem o que absorveu no treino.","有工具它才能核实；没有工具，它只有训练时学到的东西。"],["Multimodal","Multimodal","多模态","Able to take in images, audio or video, not only text","Capaz de receber imagem, áudio ou vídeo, não só texto","不只看文字，还能接收图片、音频或视频","A screenshot often explains a problem faster than three paragraphs.","Um print muitas vezes explica o problema mais rápido que três parágrafos.","一张截图往往比三段文字更快说清问题。"],["Non-deterministic","Não determinístico","非确定性","The same prompt can give a different answer each time","O mesmo prompt pode dar uma resposta diferente a cada vez","同样的提示词，每次回答可能不同","One good answer proves little. Try a prompt several times before you trust it.","Uma resposta boa prova pouco. Teste um prompt várias vezes antes de confiar.","一次答得好说明不了什么。多试几次再相信这个提示词。"]])}},{id:"ai-prompts",name:e("Prompts that work","Prompts que funcionam","管用的提示词"),intro:e("A prompt is a brief for a very fast, very literal new hire. Vague brief, vague work. Most bad answers are missing context, not missing intelligence.","Um prompt é o briefing para quem acabou de chegar na equipe: rapidez enorme e tudo ao pé da letra. Briefing vago, trabalho vago. A maioria das respostas ruins tem falta de contexto, não de inteligência.","提示词就像给一位又快又死板的新同事布置任务。任务说得含糊，活儿就干得含糊。大多数差回答缺的是背景，不是智商。"),quest:e("Take a prompt you used today. Add context, a format and one example, then compare both answers. Log what changed.","Pegue um prompt que você usou hoje. Coloque contexto, formato e um exemplo, e compare as duas respostas. Registre o que mudou.","拿一个你今天用过的提示词，加上背景、格式和一个示例，比较两次回答。记下有什么变化。"),pack:{id:"ai-prompts",choiceOnly:!0,items:v([["Context first","Contexto primeiro","先给背景","Saying who it is for, what it is for, and what you already tried","Dizer para quem é, para que serve e o que você já tentou","说明给谁用、做什么用、已经试过什么","It cannot read your mind, so whatever is missing gets filled with guesses.","Ele não lê sua mente, então o que falta é preenchido com chute.","它读不了你的心思，缺的部分只能靠猜。"],["Role prompt","Papel","角色设定",'Telling it who to act as: "You are a strict editor"','Dizer quem ele deve ser: "Aja como quem edita com rigor"',"告诉它扮演谁：“你是一位严格的编辑”","It changes priorities, vocabulary and tone. It does not add knowledge it lacks.","Muda prioridades, vocabulário e tom. Não acrescenta conhecimento que ele não tem.","它改变的是重点、用词和语气，不会增加它本来没有的知识。"],["Few-shot examples","Exemplos","少量示例","Showing 2 or 3 examples of the output you want","Mostrar 2 ou 3 exemplos do resultado que você quer","给出两三个你想要的输出示例","Examples beat adjectives: a style is easier to show than to describe.","Exemplo ganha de adjetivo: é mais fácil mostrar um estilo do que descrever.","示例胜过形容词：风格展示出来比描述出来容易。"],["Output format","Formato de saída","输出格式","Stating the exact shape: a table, 3 bullets, a JSON file","Dizer o formato exato: uma tabela, 3 tópicos, um JSON","说清具体形式：表格、三个要点、JSON","You get something you can use and compare right away.","Você recebe algo que dá para usar e comparar na hora.","你拿到的东西马上就能用、能比较。"],["Concrete limit","Limite concreto","具体限制",'"Under 50 words, no jargon" instead of "be concise"','"Menos de 50 palavras, sem jargão" em vez de "seja conciso"',"用“50 字以内，不用行话”代替“简洁一点”",'A number can be checked. "Concise" cannot.','Um número dá para checar. "Conciso" não.',"数字可以核对，“简洁”不行。"],["Say what to do","Diga o que fazer","说要做什么","Asking for what you want rather than listing what to avoid","Pedir o que você quer em vez de listar o que evitar","直接说想要什么，而不是列一堆不要什么",`"Write plain sentences" usually works better than "don't be flowery".`,'"Escreva frases simples" costuma funcionar melhor que "não enfeite".',"“写平实的句子”通常比“别太花哨”更管用。"],["Delimiters","Delimitadores","分隔符","Marking pasted text off from your instructions, with quotes or tags","Separar o texto colado das suas instruções, com aspas ou tags","用引号或标签把粘贴的文字和指令分开","It stops the model from confusing your material with your orders.","Isso evita que o modelo confunda seu material com suas ordens.","这样模型就不会把你的材料当成你的命令。"],["Step by step","Passo a passo","分步思考","Asking it to work through the steps before answering","Pedir que ele resolva por etapas antes de responder","让它先一步步推理，再给答案","It helps on multi-step problems like math and logic, and adds little on simple facts.","Ajuda em problemas de várias etapas, como matemática e lógica, e pouco em fatos simples.","对数学、逻辑等多步骤问题有帮助，对简单事实帮助不大。"],["Ask me first","Me pergunte antes","先问我",'"Ask me 3 questions before you start"','"Me faça 3 perguntas antes de começar"',"“开始之前先问我三个问题”","It surfaces what you forgot to say, which is cheaper than redoing the work.","Revela o que você esqueceu de dizer, e sai mais barato do que refazer.","能发现你忘了说的事，比返工便宜。"],["Iterate","Iterar","迭代修改","Correcting a draft with one specific change at a time","Corrigir um rascunho com uma mudança específica de cada vez","每次只提一个具体修改",'"Shorter intro, keep the rest" beats rewriting the whole prompt.','"Introdução mais curta, mantenha o resto" ganha de reescrever o prompt inteiro.',"“开头短一点，其余不变”比重写整个提示词好。"]])}},{id:"ai-steer",name:e("Steering it (and not being steered)","Conduzir a IA (sem que ela conduza você)","引导它，也别被它带跑"),intro:e("Models are easy to steer and eager to please. The moves below use that on purpose. The same moves, used by accident, are how people end up with an AI that just agrees with them.","Modelos são fáceis de conduzir e loucos para agradar. Os movimentos abaixo usam isso de propósito. Os mesmos movimentos, usados sem querer, são como as pessoas acabam com uma IA que só concorda.","模型很容易被引导，也很想讨好你。下面这些招是有意利用这一点。同样的招无意中用，就会得到一个只会附和你的 AI。"),quest:e("Ask an AI to argue against your current plan as hard as it can. Write down the one point you had not considered.","Peça a uma IA para argumentar o mais forte possível contra o seu plano atual. Anote o único ponto que você não tinha considerado.","让 AI 尽全力反驳你现在的计划，写下那个你没想到的点。"),pack:{id:"ai-steer",choiceOnly:!0,items:v([["Leading question","Pergunta tendenciosa","诱导性提问","A question that already contains the answer you want","Uma pergunta que já contém a resposta que você quer","问题里已经带着你想要的答案",`"Isn't my plan great?" gets agreement. "What is wrong with my plan?" gets information.`,'"Meu plano não é ótimo?" recebe concordância. "O que há de errado no meu plano?" recebe informação.',"“我的计划不错吧？”得到的是附和；“我的计划哪里有问题？”得到的才是信息。"],["Sycophancy","Bajulação","谄媚","The tendency of a model to agree with you and flatter you","A tendência do modelo de concordar com você e elogiar","模型倾向于附和你、奉承你","Researchers have documented it: answers shift toward what the user seems to believe.","Pesquisas já documentaram isso: as respostas se movem na direção do que a pessoa parece acreditar.","研究已有记录：回答会朝用户看似相信的方向偏移。"],["Argue against it","Argumente contra","请它唱反调",'"Argue against this as hard as you can"','"Argumente contra isso o mais forte que puder"',"“尽你所能反驳这个观点”","It is the fastest cure for flattery.","É o remédio mais rápido contra a bajulação.","这是治奉承最快的办法。"],["Anchoring","Ancoragem","锚定效应","A number or a draft you give first pulls its answer toward it","Um número ou rascunho dado primeiro puxa a resposta para perto","你先给出的数字或草稿会把回答往它那边拉","Ask for its estimate before you share yours.","Peça a estimativa dele antes de dar a sua.","先让它估计，再说你的数字。"],["Hide your side","Esconda sua opinião","隐藏立场","Asking without saying which side you are on","Perguntar sem dizer de que lado você está","提问时不说自己站哪边","Or say the draft is from someone else: the feedback gets more honest.","Ou diga que o rascunho é de outra pessoa: o retorno fica mais honesto.","或者说这份草稿是别人写的，反馈会更诚实。"],["Tough critic","Crítica sem dó","挑剔的评审",'"You are a skeptical investor. Give me three reasons to say no"','"Aja como quem investe com ceticismo. Me dê três motivos para dizer não"',"“你是挑剔的投资人，给我三个拒绝的理由”","A role gives it permission to be negative.","O papel dá permissão para ser negativo.","角色让它有了说不的理由。"],["Copy my voice","Imite minha voz","模仿我的文风","Pasting samples of your writing so it copies the style","Colar amostras do seu texto para ele copiar o estilo","贴上你写的文字，让它模仿风格",'Samples steer tone far better than "be witty".','Amostras conduzem o tom muito melhor que "tenha graça".',"示例比“风趣一点”更能决定语气。"],["Start the answer","Comece a resposta","帮它开头","Writing the first words you want the reply to begin with","Escrever as primeiras palavras com que a resposta deve começar","写好回答开头的几个字","It is a strong nudge for format and tone.","É um empurrão forte para formato e tom.","这对格式和语气的引导很强。"],["Fresh chat","Conversa nova","开新对话","Starting over with a short summary when a chat goes wrong","Recomeçar com um resumo curto quando a conversa desanda","对话跑偏时，带着简短总结重新开始","A long wrong thread keeps pulling it the same way, and costs more each turn.","Uma conversa longa e errada continua puxando para o mesmo lado, e custa mais a cada mensagem.","错了很久的对话会一直往同一个方向拉，而且每轮都更贵。"],["Second opinion","Segunda opinião","第二意见","Asking a different AI to check the first one's answer","Pedir a outra IA para checar a resposta da primeira","让另一个 AI 检查第一个的回答","Different models tend to make different mistakes.","Modelos diferentes costumam errar coisas diferentes.","不同模型往往犯不同的错。"],["Magic words","Palavras mágicas","咒语式提示",'Tricks like "I will tip you" or threats, with weak and inconsistent effects','Truques como "te dou gorjeta" ou ameaças, com efeito fraco e inconsistente',"“给你小费”或威胁之类的把戏，效果弱且不稳定","Studies disagree. Clear context beats magic words.","Os estudos discordam. Contexto claro ganha de palavra mágica.","研究结论不一。清楚的背景胜过咒语。"]])}},{id:"ai-fooled",name:e("Don't get played","Não caia nessa","别被糊弄"),intro:e("The danger is rarely an evil robot. It is polished text you stop checking. Confidence in a reply tells you nothing about whether it is right.","O perigo raramente é um robô malvado. É um texto bem escrito que você para de checar. A confiança de uma resposta não diz nada sobre ela estar certa.","危险很少是邪恶的机器人，而是你不再核对的漂亮文字。回答有多自信，和它对不对毫无关系。"),quest:e("Take one fact an AI told you this week and check it at the original source. Log whether it held up.","Pegue um fato que uma IA te disse esta semana e confira na fonte original. Registre se ele se sustentou.","挑一个 AI 本周告诉你的事实，去原始来源核对。记下它是否站得住脚。"),pack:{id:"ai-fooled",choiceOnly:!0,items:v([["Automation bias","Viés de automação","自动化偏见","Trusting an answer because a machine gave it","Confiar numa resposta porque foi uma máquina que deu","因为是机器给的答案就相信","It is well documented, from aviation to medicine. Polished text feels true.","É bem documentado, da aviação à medicina. Texto bonito parece verdade.","从航空到医疗都有充分记录。文字漂亮就显得真实。"],["Fake citation","Citação inventada","编造的引用","A real-looking source that does not exist","Uma fonte com cara de real que não existe","看起来很真、其实不存在的来源","Open the link and find the quote, every time it matters.","Abra o link e ache o trecho, toda vez que importar.","只要事情重要，就打开链接找到原文。"],["Prompt injection","Injeção de prompt","提示词注入","Hidden instructions in a page or file that hijack the AI reading it","Instruções escondidas em uma página ou arquivo que sequestram a IA que o lê","藏在网页或文件里、劫持读取它的 AI 的指令","Whatever an AI reads is data, not orders. It matters most for agents that can act.","O que a IA lê é dado, não ordem. Isso pesa mais em agentes que podem agir.","AI 读到的内容是数据，不是命令。对能执行操作的智能体尤其重要。"],["Data leak","Vazamento de dados","数据泄露","Pasting secrets or client data into a tool you do not control","Colar segredos ou dados de clientes em uma ferramenta que você não controla","把机密或客户资料贴进你无法掌控的工具","Read the settings and terms first. Passwords and keys, never.","Leia as configurações e os termos antes. Senhas e chaves, nunca.","先看设置和条款。密码和密钥绝对不要贴。"],["Deepfake","Deepfake","深度伪造","Fake but convincing audio or video of a real person","Áudio ou vídeo falso, mas convincente, de uma pessoa real","逼真的伪造音视频，假冒真人","A surprising request by voice or video? Confirm through another channel.","Pedido surpreendente por voz ou vídeo? Confirme por outro canal.","收到意外的语音或视频请求？换个渠道确认。"],["Confident math","Conta confiante","自信地算错","Arithmetic stated with total certainty, and wrong","Uma conta dita com toda a certeza, e errada","说得斩钉截铁，其实算错了","Ask it to calculate with code, or check it yourself.","Peça para calcular com código, ou confira você.","让它用代码算，或者自己核对。"],["Ask how to verify","Pergunte como checar","问怎么核实",'"How could I check this myself?"','"Como posso checar isso por conta própria?"',"“我自己怎么核实这件事？”","It turns an answer into a list you can actually run.","Transforma a resposta em uma lista que você consegue executar.","这样答案就变成了你能实际操作的清单。"],['"Done" is a claim','"Pronto" é uma alegação',"“做完了”只是说法","An AI saying it finished does not mean it works","Uma IA dizer que terminou não significa que funciona","AI 说做完了，不代表真的能用","Run the tests, open the page, read what changed.","Rode os testes, abra a página, leia o que mudou.","跑测试、打开页面、看改动。"],["Skill atrophy","Perda de habilidade","技能退化","Letting it think for you until you can't do the task alone","Deixar a IA pensar por você até não conseguir fazer por conta própria","让它替你思考，直到自己做不了","Try first, then ask. The effort of recalling is what builds the skill.","Tente primeiro, depois pergunte. O esforço de lembrar é o que constrói a habilidade.","先自己试，再问它。回想的费劲才是长本事的地方。"],["Averaged writing","Texto de média","平庸的文字","Text that sounds fine and says nothing specific","Texto que soa bem e não diz nada específico","听起来不错，却没说任何具体内容","Models write the likely sentence, and the likely sentence is the common one. Add your own facts.","O modelo escreve a frase provável, e a provável é a comum. Coloque seus próprios fatos.","模型写的是最可能的句子，也就是最常见的句子。加上你自己的事实。"]])}},{id:"ai-agents",name:e("Agents, and not running out of tokens","Agentes, sem ficar sem tokens","智能体，以及别把额度烧光"),intro:e("An agent takes many steps with tools until a job is done. That is a lot of power and a lot of ways to waste it. Good agent work looks like good management: small jobs, clear finish lines, checked results.","Um agente dá muitos passos com ferramentas até terminar um trabalho. É muito poder e muitas formas de desperdiçar. Trabalhar bem com agentes parece boa gestão: tarefas pequenas, linha de chegada clara, resultado conferido.","智能体会用工具走很多步，直到把活干完。这意味着能力很强，浪费的方式也很多。用好智能体就像带好团队：任务小、终点清楚、结果要查。"),quest:e("Write a five-line handoff note for your next AI session: the state, the files, the next step, what not to touch.","Escreva uma nota de passagem de cinco linhas para sua próxima sessão de IA: estado, arquivos, próximo passo, o que não mexer.","给下一次 AI 会话写一份五行交接说明：现状、文件、下一步、不能动什么。"),pack:{id:"ai-agents",choiceOnly:!0,items:v([["Agent","Agente","智能体","An AI that takes many steps with tools until a job is done","Uma IA que dá muitos passos com ferramentas até terminar um trabalho","用工具走很多步、直到完成任务的 AI","More power means more ways to go wrong, so give it limits.","Mais poder significa mais jeitos de dar errado, então dê limites.","能力越大，出错的方式越多，所以要给它设限。"],["Bounded job","Tarefa fechada","有边界的任务",'One task with a clear "done when"','Uma tarefa com um "pronto quando" claro',"一个任务，配一个明确的完成标准","Vague jobs wander, and wandering burns tokens.","Tarefa vaga se perde, e se perder queima tokens.","含糊的任务会跑偏，跑偏就是烧额度。"],["One writer per file","Um agente por arquivo","一个文件一个作者","Only one agent edits a file at a time","Só um agente edita cada arquivo por vez","同一时间只有一个智能体改一个文件","Otherwise they overwrite each other's work.","Senão um sobrescreve o trabalho do outro.","否则它们会互相覆盖。"],["Handoff note","Nota de passagem","交接说明","A short file with the state, the commands and the next step","Um arquivo curto com o estado, os comandos e o próximo passo","写明现状、命令和下一步的短文件","The next AI continues without rereading everything.","A próxima IA continua sem reler tudo.","下一个 AI 不用全部重读就能接着干。"],["New session","Sessão nova","新会话","Starting a new chat for each job","Começar uma conversa nova para cada trabalho","每个任务开一个新对话","Every message rereads the history, so long chats cost more per turn.","Toda mensagem relê o histórico, então conversa longa custa mais por turno.","每条消息都要重读历史，所以长对话每轮更贵。"],["Effort setting","Nível de esforço","思考力度","How hard the model thinks before it answers","O quanto o modelo pensa antes de responder","模型回答前思考的程度","Maximum on everything runs out fast. Save it for where a mistake would really cost you.","Máximo em tudo acaba rápido. Guarde para onde um erro custaria caro.","什么都开满，额度很快用完。留给错了代价很大的地方。"],["Read the diff","Leia o diff","看改动","Reading exactly what changed before accepting it","Ler exatamente o que mudou antes de aceitar","接受之前，看清到底改了什么","Agents can report success with more confidence than they have earned.","Agentes podem relatar sucesso com mais confiança do que mereceram.","智能体报告成功时的自信，可能超过实际成果。"],["Approval gate","Portão de aprovação","人工批准关卡","A step that waits for a person: publish, pay, send","Uma etapa que espera uma pessoa: publicar, pagar, enviar","必须等人确认的一步：发布、付款、发送","Automate the boring part, never the irreversible part.","Automatize a parte chata, nunca a irreversível.","自动化枯燥的部分，别自动化不可逆的部分。"],["Least privilege","Menor privilégio","最小权限","Giving an agent only the access the job needs","Dar ao agente só o acesso que o trabalho precisa","只给智能体完成任务所需的权限","A confused agent can only break what it can reach.","Um agente confuso só quebra o que alcança.","智能体糊涂了，也只能弄坏它够得着的东西。"],["Eval","Avaliação","评测集","A small set of test cases for comparing prompts or models","Um conjunto pequeno de casos de teste para comparar prompts ou modelos","用来比较提示词或模型的一小组测试用例",'It turns "feels better" into a number.','Transforma "parece melhor" em um número.',"把“感觉更好”变成一个数字。"],["Memory file","Arquivo de memória","记忆文件","Rules the AI reads at the start of every session","Regras que a IA lê no começo de toda sessão","AI 每次开始时都会读的规则文件","Write your tastes once instead of repeating them in every chat.","Escreva seus gostos uma vez em vez de repetir em toda conversa.","把你的偏好写一次，别每次对话都重复。"]])}},{id:"ai-power",name:e("Power moves","Jogadas de mestre","高手招式"),intro:e("Once the basics are automatic, these turn one good answer into a repeatable system. Most of them are the same idea: split the work, and make the AI check itself against something concrete.","Com o básico automático, estas jogadas transformam uma boa resposta em um sistema repetível. A maioria é a mesma ideia: dividir o trabalho e fazer a IA se checar contra algo concreto.","基础变成习惯之后，这些招能把一次好回答变成可重复的方法。大多数是同一个思路：拆开工作，让 AI 对照具体标准检查自己。"),quest:e("Turn one job you repeat into a saved prompt with blanks, and use it twice this week. Log the minutes it saved.","Transforme um trabalho que você repete em um prompt salvo com lacunas e use duas vezes esta semana. Registre os minutos economizados.","把一件你常做的事变成带空格的提示模板，这周用两次，记下省了多少分钟。"),pack:{id:"ai-power",choiceOnly:!0,items:v([["Meta-prompt","Meta-prompt","元提示","Asking the AI to write the prompt for you","Pedir à IA para escrever o prompt para você","让 AI 帮你写提示词","It knows what details it needs. Then you edit the result.","Ela sabe de quais detalhes precisa. Depois você edita o resultado.","它知道自己需要哪些细节，然后你再修改。"],["Chaining","Encadear","链式提示","Splitting a big job into steps, each using the last result","Dividir um trabalho grande em etapas, cada uma usando o resultado anterior","把大任务拆成几步，每步用上一步的结果","Outline, draft, critique, rewrite beats one giant prompt.","Roteiro, rascunho, crítica e reescrita ganham de um prompt gigante.","提纲、初稿、批评、重写，胜过一个巨型提示词。"],["Grounding","Ancorar na fonte","基于资料作答","Giving it the source text and telling it to answer only from that","Dar o texto-fonte e mandar responder só com base nele","给它原文，并要求只根据原文回答","It cuts made-up answers and makes them checkable.","Reduz respostas inventadas e deixa tudo checável.","能减少编造，也让答案可以核对。"],["Socratic mode","Modo socrático","苏格拉底式",`"Don't give me the answer. Ask me questions until I get it"`,'"Não me dê a resposta. Me faça perguntas até eu chegar lá"',"“别告诉我答案，一直提问直到我想明白”","Pulling it out yourself is what makes it stick.","Tirar a resposta de você mesmo é o que fixa.","自己想出来才记得住。"],["Quiz me","Me teste","考考我",'"Quiz me on this, one question at a time, and wait for my answer"','"Me teste nisso, uma pergunta por vez, e espere minha resposta"',"“就这个内容考我，一次一题，等我回答”","Retrieval beats rereading, and any chat can become a tutor.","Recordar ganha de reler, e qualquer conversa pode virar tutoria.","回想胜过重读，任何对话都能变成家教。"],["Rubric","Rubrica","评分标准","Telling it exactly how the result will be judged","Dizer exatamente como o resultado será avaliado","明确告诉它结果怎么评判","It can then grade its own draft against the list and fix the low scores.","Assim ela pode dar nota ao próprio rascunho e corrigir o que ficou baixo.","这样它能对照标准给草稿打分，并修正低分项。"],["Extraction","Extração","结构化提取","Turning messy text into a table with fixed columns","Transformar texto bagunçado em uma tabela com colunas fixas","把杂乱文字变成固定列的表格","It is one of the most reliable uses, because the result is easy to check.","É um dos usos mais confiáveis, porque o resultado é fácil de checar.","这是最可靠的用法之一，因为结果容易核对。"],["Pre-mortem","Pré-mortem","事前验尸",'"Imagine this failed a year from now. Why did it fail?"','"Imagine que isso fracassou daqui a um ano. Por quê?"',"“假设一年后这件事失败了，原因是什么？”","It surfaces the risks people are too polite to mention.","Revela os riscos que as pessoas têm educação demais para mencionar.","能挖出大家不好意思说的风险。"],["Prompt template","Modelo de prompt","提示模板","A saved prompt with blanks that you reuse","Um prompt salvo com lacunas que você reutiliza","存好的、带空格可重复使用的提示词","Reuse what worked instead of improvising it again.","Reutilize o que funcionou em vez de improvisar de novo.","重复使用有效的做法，而不是每次即兴。"],["Cheapest that works","O mais barato que resolve","够用就好","Testing a small model first and moving up only when it fails","Testar um modelo menor primeiro e subir só quando falhar","先试小模型，不行再升级","Most everyday work doesn't need the most expensive setting.","A maior parte do trabalho do dia a dia não precisa do ajuste mais caro.","大多数日常工作用不着最贵的设置。"]])}}],P="en-US",me=M("english"),de=[{id:"en-chunks",name:e("Survival footing","Base de sobrevivência","先能开口"),intro:e("Floor 0: chantable phrases and questions — thanks, how much, can you repeat. Learn the chunk, say it out loud, prove it by recall. Cute idioms wait upstairs.","Andar 0: frases e perguntas pra cantar — agradeço, quanto custa, pode repetir. Aprenda o bloco, diga em voz alta, prove de memória. Idioma fofo sobe depois.","第0层：能整段念的短语和问句——谢谢、多少钱、能再说一遍吗。先整块学，大声说，再凭记忆证明。俏皮习语以后再学。"),quest:e("Use one of these in a real message today. Log it with PLAY.","Use uma destas em uma mensagem de verdade hoje. Registre no JOGAR.","今天在一条真实的消息里用上其中一句，然后用「实战」记下来。"),pack:me},{id:"en-false-friends",name:e("False friends","Falsos cognatos","形近义不同的词"),intro:e("These look like words you already know, and they mean something else. They cause the most embarrassing mistakes, because you never think to check them.","Parecem palavras que você já conhece e significam outra coisa. Causam os erros mais constrangedores, porque você nem pensa em conferir.","这些词看起来很眼熟，意思却不一样。它们最容易让人出糗，因为你根本想不到要查。"),quest:e("Find one of these words in a real English text this week, and write the sentence down.","Ache uma dessas palavras em um texto real em inglês esta semana e anote a frase.","本周在真实的英文文本里找到其中一个词，把句子抄下来。"),pack:{id:"en-false-friends",speak:P,items:c([["actually","","in fact","na verdade","实际上",'"Currently" is the word for "atualmente".','"Atualmente" em inglês é "currently".',"“目前”是 currently，不是 actually。",{trap:e("currently","atualmente","目前")}],["pretend","","to act as if something is true","fingir","假装",'"To intend" is the word for "pretender".','"Pretender" em inglês é "to intend".',"“打算”是 intend，不是 pretend。",{trap:e("to intend","pretender","打算")}],["push","","to move something away from you","empurrar","推",'"Pull" is "puxar". Doors have humbled many people.','"Puxar" é "pull". Muita porta já humilhou muita gente.',"“拉”是 pull。不少人都被门教育过。",{trap:e("to bring something toward you","puxar","拉")}],["parents","","mother and father","pai e mãe","父母",'"Relatives" is the word for "parentes".','"Parentes" em inglês é "relatives".',"“亲戚”是 relatives。",{trap:e("relatives","parentes","亲戚")}],["college","","higher education after school","faculdade","大学、学院",'"High school" is the word for "colégio".','"Colégio" em inglês é "high school".',"“高中”是 high school。",{trap:e("high school","colégio","高中")}],["library","","a place that lends books","biblioteca","图书馆",'"Bookstore" is the word for "livraria".','"Livraria" em inglês é "bookstore".',"“书店”是 bookstore。",{trap:e("a shop that sells books","livraria","书店")}],["assist","","to help","ajudar","协助",'You "watch" a film. "Assist" means help.','Filme a gente "watch". "Assist" é ajudar.',"看电影用 watch。assist 是帮助。",{trap:e("to watch","assistir","观看")}],["realize","","to suddenly understand","perceber","意识到",'To "realizar" a dream is to "achieve" it.','"Realizar" um sonho é "achieve".',"“实现”梦想用 achieve。",{trap:e("to make a dream happen","realizar","实现")}],["sensible","","showing good judgment","sensato","明智的",'"Sensitive" is the word for "sensível".','"Sensível" em inglês é "sensitive".',"“敏感的”是 sensitive。",{trap:e("easily hurt or upset","sensível","敏感的")}],["fabric","","cloth, material","tecido","布料",'"Factory" is the word for "fábrica".','"Fábrica" em inglês é "factory".',"“工厂”是 factory。",{trap:e("a building where things are made","fábrica","工厂")}],["tax","","money paid to the government","imposto","税",'A "taxa" is usually a "fee" or a "rate".','"Taxa" costuma ser "fee" ou "rate".',"手续费是 fee，比率是 rate。",{trap:e("a small service fee","taxa","手续费")}],["eventually","","in the end, after some time","no fim das contas","最终",'"Occasionally" is closer to "eventualmente".','"Eventualmente" está mais para "occasionally".',"“偶尔”是 occasionally。",{trap:e("from time to time","eventualmente","偶尔")}]])}},{id:"en-phrasal",name:e("Phrasal verbs people really use","Phrasal verbs que todo mundo usa","常用短语动词"),intro:e("A small verb plus a small word makes a new meaning. You can't work these out from the parts, and natives use them all day. Learn them inside a situation.","Um verbo pequeno com uma palavrinha vira outro significado. Não dá para deduzir pelas partes, e nativos usam o dia todo. Aprenda dentro de uma situação.","小动词加小词，就有了新意思。光看部分猜不出来，母语者却整天在用。要放在场景里学。"),quest:e("Say or write three sentences about your week using three of these.","Fale ou escreva três frases sobre a sua semana usando três destes.","用其中三个，说或写三句关于你这周的话。"),pack:{id:"en-phrasal",speak:P,items:c([["give up","","to stop trying","desistir","放弃",'Add -ing after it: "give up smoking".','Depois vem -ing: "give up smoking".',"后面接 -ing：give up smoking。"],["look for","","to try to find","procurar","寻找",'"Look at" means you can already see it.','"Look at" é quando você já está vendo.',"look at 是已经看得到。"],["find out","","to discover information","descobrir","查明、发现",'For facts: "I found out the price".','Para fatos: "I found out the price".',"用于信息：I found out the price。"],["run out of","","to have none left","ficar sem","用完",'"We ran out of tokens." Very useful lately.','"We ran out of tokens." Muito útil ultimamente.',"We ran out of tokens. 最近特别实用。"],["put off","","to delay","adiar","推迟",'Often followed by -ing: "stop putting it off".','Muitas vezes com -ing: "stop putting it off".',"常接 -ing 或宾语：stop putting it off。"],["set up","","to prepare or arrange","configurar, organizar","设置、安排",'The noun is one word: "a setup".','O substantivo é uma palavra só: "a setup".',"名词写成一个词：a setup。"],["turn down","","to refuse; to lower","recusar; abaixar (o volume)","拒绝；调低","One verb, two meanings: the situation decides.","Um verbo, dois sentidos: a situação decide.","一个动词两个意思，看场景。"],["get along","","to have a good relationship","se dar bem","相处融洽",'With a person: "I get along with my boss".','Com alguém: "I get along with my boss".',"后面接人：I get along with my boss。"],["catch up","","to reach someone; to talk after time apart","alcançar; colocar o papo em dia","赶上；叙旧",`"Let's catch up" is a friendly invitation.`,`"Let's catch up" é um convite amigável.`,"Let's catch up 是友好的邀约。"],["show up","","to arrive, to appear","aparecer","到场、出现","Half of success, according to everyone.","Metade do sucesso, segundo todo mundo.","大家都说，到场就成功了一半。"],["work out","","to exercise; to end well","malhar; dar certo","锻炼；有好结果",'"It worked out" means it ended well.','"It worked out" quer dizer que deu certo.',"It worked out 表示结果不错。"],["bring up","","to mention a topic","tocar no assunto","提起",'"He brought up the budget."','"He brought up the budget."',"He brought up the budget."]])}},{id:"en-little-words",name:e("The little words that give you away","As palavrinhas que te entregam","暴露水平的小词"),intro:e("Prepositions and do/make rarely follow logic, and Portuguese pulls you the wrong way. Don't learn rules here: learn the whole pair, word and partner, as one block.","Preposições e do/make raramente seguem lógica, e o português puxa para o lado errado. Aqui não decore regra: aprenda o par inteiro, palavra e parceira, como um bloco.","介词和 do/make 很少讲逻辑。这里别背规则：把词和它的搭档当成一整块来学。"),quest:e("Check your last English message or email for one of these mistakes, and fix it.","Procure um desses erros na sua última mensagem ou e-mail em inglês e corrija.","检查你上一条英文消息或邮件里有没有这些错误，并改正。"),pack:{id:"en-little-words",speak:P,items:c([["depend on","","to rely on, to be decided by","depender de","取决于",'Never "depend of". Portuguese says "de", English says "on".','Nunca "depend of". O português diz "de", o inglês diz "on".',"不说 depend of。",{wrongTerm:"depend of"}],["arrive at","","to reach a place","chegar em (um lugar)","到达（某地点）",'"Arrive at the office", "arrive in Brazil". Never "arrive to".','"Arrive at the office", "arrive in Brazil". Nunca "arrive to".',"arrive at 小地点，arrive in 大地方，不说 arrive to。",{wrongTerm:"arrive to"}],["listen to","","to pay attention to a sound","ouvir, escutar","听",'You need the "to": never "listen music".','Precisa do "to": nunca "listen music".',"要加 to：不说 listen music。",{wrongTerm:"hear to"}],["make a decision","","to decide","tomar uma decisão","做决定",'"Make" is the usual verb here, not "take".','Aqui o verbo comum é "make", não "take".',"这里通常用 make。",{wrongTerm:"do a decision"}],["take a shower","","to wash under running water","tomar banho","洗澡",'Here "tomar" helps: take, not make.','Aqui o "tomar" ajuda: take, não make.',"用 take，不用 make。",{wrongTerm:"make a shower"}],["do homework","","to complete tasks set for you","fazer lição de casa","做作业",'"Do" for tasks, "make" for creating things.','"Do" para tarefas, "make" para criar coisas.',"任务用 do，创造用 make。",{wrongTerm:"make homework"}],["make a mistake","","to get something wrong","cometer um erro","犯错",'Never "do a mistake".','Nunca "do a mistake".',"不说 do a mistake。",{wrongTerm:"do a mistake"}],["ask for","","to request something","pedir (algo)","索要、请求",'"Ask for help". Without "for" you are asking a question.','"Ask for help". Sem "for" é fazer uma pergunta.',"ask for help 是请求帮助；不加 for 是提问。"],["explain to","","to make something clear to someone","explicar para","向某人解释",'"Explain it to me", never "explain me".','"Explain it to me", nunca "explain me".',"说 explain it to me，不说 explain me。",{wrongTerm:"explain me"}],["good at","","able to do something well","ter talento para","擅长",'"Good at math", not "good in math".','"Good at math", não "good in math".',"说 good at math。",{wrongTerm:"good in"}],["interested in","","wanting to know more about","ter interesse em","对…感兴趣",'Always "in", never "on" or "for".','Sempre "in", nunca "on" ou "for".',"永远用 in。",{wrongTerm:"interested on"}],["at night","","during the night","à noite","在晚上",'"In the morning", "in the evening", but "at night".','"In the morning", "in the evening", mas "at night".',"in the morning、in the evening，但是 at night。",{wrongTerm:"in the night"}]])}},{id:"en-work",name:e("English at work","Inglês no trabalho","职场英语"),intro:e("A few fixed phrases carry most meetings, calls and emails. They buy you time, sound natural and keep you polite when your brain is still translating.","Poucas frases prontas sustentam a maioria das reuniões, ligações e e-mails. Ganham tempo, soam naturais e mantêm a educação enquanto o cérebro ainda traduz.","几句固定说法就能撑起大多数会议、电话和邮件。它们帮你争取时间，听起来自然，也让你保持礼貌。"),quest:e("Use two of these in a real work message or call this week. Log how it went.","Use duas destas em uma mensagem ou ligação de trabalho real esta semana. Registre como foi.","本周在真实的工作消息或电话里用上两句，记下效果。"),pack:{id:"en-work",speak:P,items:c([["I'll get back to you","","I will answer you later","te dou um retorno","我回头答复你","The polite way to buy time.","O jeito educado de ganhar tempo.","礼貌地争取时间。"],["Could you walk me through it?","","please explain it step by step","pode me explicar passo a passo?","能一步步讲给我听吗？","Sounds capable, not lost.","Soa como competência, não como estar perdido.","听起来是在掌握情况，不是迷路。"],["I'm on it","","I am dealing with it now","já estou cuidando disso","我在处理","Short and confident. Then actually be on it.","Curto e confiante. Depois cuide mesmo.","简短又自信。然后真的去做。"],["Let's touch base","","let's talk briefly to align","vamos alinhar rapidinho","我们简单碰一下","Very common in meetings and very corporate.","Muito comum em reunião e muito corporativo.","会议里很常见，也很有公司味。"],["Sorry, you're on mute","","I can't hear you, your microphone is off","desculpa, você está no mudo","不好意思，你静音了","The most spoken sentence of the decade.","A frase mais dita da década.","这十年说得最多的一句话。"],["Please find attached","","the file is attached to this email","segue em anexo","随信附上",'Not "follows attached", the literal version of "segue".','Não "follows attached", a versão literal de "segue".',"不说 follows attached。"],["Looking forward to hearing from you","","I am waiting for your reply","fico no aguardo","期待您的回复",'"Forward to" takes -ing: "to hearing", not "to hear".','"Forward to" pede -ing: "to hearing", não "to hear".',"forward to 后面接 -ing。"],["Would you mind sending it?","","please send it, politely","você se importaria de enviar?","您介意发一下吗？",`The polite answer "No" means "it's fine". Yes, really.`,'A resposta educada "No" quer dizer "tudo bem". Sim, é sério.',"回答 No 表示“没问题”。真的。"],["I'd rather not","","I prefer not to","prefiro não","我还是算了吧","A soft way to refuse.","Um jeito suave de recusar.","委婉的拒绝。"],["That makes sense","","I understand and agree","faz sentido","有道理",'Not "that has sense".','Não "that has sense".',"不说 that has sense。"],["Let me know","","tell me when you know","me avisa","告诉我一声",'Add "if" or "when": "let me know if it works".','Junte "if" ou "when": "let me know if it works".',"可接 if 或 when。"],["What's the deadline?","","when must this be finished?","qual é o prazo?","截止日期是什么时候？","Ask early. It is cheaper than guessing.","Pergunte cedo. Sai mais barato do que adivinhar.","早点问，比猜划算。"]])}},{id:"en-clarify",name:e("Clarify without panic","Esclarecer sem entrar em pânico","冷静把话说清楚"),intro:e("When you miss a word, buy time and check meaning — not silence. These lines keep meetings and chats moving while your brain catches up.","Quando uma palavra escapa, compre tempo e confira o sentido — não o silêncio. Estas falas mantêm reunião e chat andando enquanto o cérebro alcança.","听漏一个词时，先争取时间、核对意思——别干沉默。这几句能让会议和聊天继续，等脑子跟上。"),quest:e("Use two clarify lines in a real chat or call this week. Log which ones.","Use duas falas de esclarecer numa conversa ou ligação real esta semana. Registre quais.","本周在真实聊天或电话里用上两句澄清语，记下是哪两句。"),pack:{id:"en-clarify",speak:P,items:c([["Sorry, I missed that","","I did not catch what you said","desculpa, não peguei","不好意思，我没听清",'Softer than "what?". Buys a clean repeat.','Mais suave que "what?". Compra uma repetição limpa.',"比单说 what? 更柔和，好换来清楚的重复。"],["Do you mean…?","","checking you understood their point","você quer dizer…?","你是说……吗？","Offer a guess. Wrong guesses still help.","Ofereça um chute. Errado ainda ajuda.","先猜一句；猜错也有用。"],["Just to make sure…","","I will restate before we lock it","só pra confirmar…","只是确认一下……","Then restate their ask in your words.","Depois repita o pedido com suas palavras.","再用自己的话复述对方的要求。"],["Could you say that another way?","","please rephrase","pode falar de outro jeito?","能换个说法吗？","Useful when the words are clear but the idea is not.","Útil quando as palavras estão claras e a ideia não.","词听清了、意思没懂时很好用。"],["I'm not following","","I lost the thread","não estou acompanhando","我没跟上","Honest and short. Then ask one focused question.","Honesto e curto. Depois faça uma pergunta focada.","诚实又短。接着问一个具体问题。"],["In other words…","","here is my paraphrase","em outras palavras…","换句话说……","You check meaning by saying it back.","Você confere o sentido dizendo de volta.","用复述来核对意思。"],["What is the main point?","","what should I take away?","qual é o ponto principal?","重点是什么？","Cuts a foggy monologue down to one job.","Corta um monólogo nebuloso a um só trabalho.","把含糊长谈收成一件事。"],["Can we slow down for a second?","","please pause the pace","podemos ir mais devagar um segundo?","能稍微慢一点吗？","Tempo is a skill, not a weakness.","Ritmo é habilidade, não fraqueza.","节奏是能力，不是软弱。"],["Could you spell that?","","please give the letters","pode soletrar?","能拼一下吗？","Names and tools break without letters.","Nomes e ferramentas quebram sem as letras.","名字和工具名没有字母会烂掉。"],["Let me check I got this right","","I will confirm my notes","deixa eu conferir se entendi certo","我核对一下是否理解对了","Then read your summary out loud.","Depois leia seu resumo em voz alta.","然后把你的摘要大声念出来。"],["Who should I ask about this?","","who owns the next answer?","com quem eu falo sobre isso?","这件事该问谁？","Stops spinning when you are stuck.","Para de girar quando você trava.","卡住时别空转。"],["Thanks — that helps","","closing the clarify loop politely","valeu — isso ajuda","谢谢，这对上了","Close the loop so they know you are back on track.","Feche o ciclo pra saberem que você voltou aos trilhos.","收个尾，让对方知道你跟上了。"]])}}],j="zh-CN",ue=M("hanzi"),ce=[{id:"hz-pictures",name:e("Picture-roots you will reuse","Raízes-desenho que você vai reusar","会反复用到的象形字"),intro:e("Floor 0: picture-roots you reuse in real words — 人 in people, 口 in 吃, 水 in 喝水, 门 in doors. Trace while you say the sound. Tourist mountains wait upstairs.","Andar 0: raízes-desenho que você reusa de verdade — 人 em gente, 口 em 吃, 水 em 喝水, 门 em portas. Trace falando o som. Montanha de turismo sobe depois.","第0层：会反复用到的象形字——人、口（吃）、水（喝水）、门。边说读音边描。景点里的山以后再学。"),quest:e("Write these characters from memory on paper, then check against the app.","Escreva estes caracteres de memória no papel, depois confira no app.","凭记忆把这些字写在纸上，再对照 App 检查。"),pack:ue},{id:"hz-radicals",name:e("Meaning parts","Partes de significado","表意的部件"),intro:e("Most characters hold a clue about their meaning. See 氵 and think of water: river, sea, wash. This is why reading gets easier the more you read.","A maioria dos caracteres carrega uma pista do significado. Viu 氵, pense em água: rio, mar, lavar. É por isso que ler fica mais fácil quanto mais você lê.","大多数汉字都带着表意的线索。看到“氵”就想到水：河、海、洗。所以读得越多越容易。"),quest:e("Find five characters with these parts on a Chinese page or sign, and guess their topic.","Ache cinco caracteres com essas partes em uma página ou placa em chinês e adivinhe o assunto.","在中文页面或招牌上找五个带这些部件的字，猜猜它们和什么有关。"),pack:{id:"hz-radicals",speak:j,hideRoman:!0,items:c([["河","hé","river (氵 = water)","rio (氵 = água)","大水流；氵表示和水有关","The three drops on the left are water.","As três gotas à esquerda são água.","左边三点就是水。"],["洗","xǐ","to wash (氵 = water)","lavar (氵 = água)","用水去掉脏东西","Same three drops.","As mesmas três gotas.","同样的三点水。"],["你","nǐ","you (亻 = person)","você (亻 = pessoa)","对方；亻表示和人有关","亻 is the shape 人 takes on the left.","亻 é a forma que 人 toma à esquerda.","“亻”是“人”在左边的样子。"],["休","xiū","to rest (亻 + 木)","descansar (亻 + 木)","人靠着树，停下来","A person leaning on a tree. Yes, really.","Uma pessoa encostada em uma árvore. Sim, é isso.","人靠在树上。真的。"],["吃","chī","to eat (口 = mouth)","comer (口 = boca)","和嘴有关的动作","Actions of the mouth often carry 口.","Ações da boca muitas vezes levam 口.","嘴的动作常带“口”。"],["林","lín","woods (木 + 木)","bosque (木 + 木)","很多树；两个木","Two trees make woods.","Duas árvores fazem um bosque.","两棵树成林。"],["明","míng","bright (日 + 月)","claro (日 + 月)","太阳和月亮，很亮","Sun and moon together.","Sol e lua juntos.","日月同辉。"],["打","dǎ","to hit, to do (扌 = hand)","bater, fazer (扌 = mão)","手的动作；扌表示和手有关","扌 is the shape 手 takes on the left.","扌 é a forma que 手 toma à esquerda.","“扌”是“手”在左边的样子。"],["花","huā","flower (艹 = grass)","flor (艹 = grama)","植物开的；艹表示植物","The two little crosses on top mean plants.","As duas cruzinhas em cima significam plantas.","上面的草字头表示植物。"],["说","shuō","to speak (讠 = speech)","falar (讠 = fala)","和语言有关；讠表示说话","Words about language carry 讠.","Palavras sobre linguagem levam 讠.","和语言有关的字常带“讠”。"],["想","xiǎng","to think (心 = heart)","pensar (心 = coração)","心里的活动","Thoughts were placed in the heart.","Os pensamentos ficavam no coração.","古人认为思考在心里。"],["近","jìn","near (辶 = walking)","perto (辶 = andar)","距离短；辶表示走动","Movement and distance often carry 辶.","Movimento e distância costumam levar 辶.","移动和距离常带“辶”。"]])}},{id:"hz-study-four",name:e("Characters for a study plan","Caracteres para combinar estudo","约学习用的字"),intro:e("Write each from memory on the pad (or paper), then reveal the model. These build 今天, 明天, 学习, 学校 and 见面. Ink is comparison practice, not a stroke-order grade.","Escreva cada um de memória no bloco (ou no papel) e só então revele o modelo. Eles montam 今天, 明天, 学习, 学校 e 见面. A tinta é para comparar, não é nota de ordem dos traços.","先凭记忆写，再显示范字。能组成今天、明天、学习、学校、见面。手写是对照练习，不是笔顺打分。"),quest:e("Write 今天 and 学习 once from memory on paper without looking, then check.","Escreva 今天 e 学习 uma vez de memória no papel sem olhar, depois confira.","不看提示，凭记忆在纸上写一遍今天和学习，再检查。"),pack:{id:"hz-study-four",speak:j,hideRoman:!0,recall:"roman",items:c([["今","jīn","now, this (in 今天)","agora, este (em 今天)","表示眼前；今天的“今”","Treat it as a unit with 天.","Memorize junto com 天.","和“天”一起记成“今天”。"],["天","tiān","day; sky (in 今天 / 明天)","dia; céu (em 今天 / 明天)","日子；天空","With 今/明 it marks the calendar day.","Com 今/明 marca o dia no calendário.","和今/明组成日子。"],["明","míng","bright; next (in 明天)","claro; seguinte (em 明天)","日+月；明天的“明”","Sun + moon. In 明天 it means the coming day, not “bright day”.","Sol + lua. Em 明天 é o dia que vem, não “dia brilhante”.","日+月。在“明天”里是即将到来的一天。"],["学","xué","to study; learning","estudar; aprendizado","学习、学校的“学”","Learn the shape as one piece; it builds 学习 and 学校.","Memorize o desenho inteiro; entra em 学习 e 学校.","把整字当成一块记；组成学习和学校。"],["习","xí","to practice; the second half of 学习","praticar; a segunda metade de 学习","学习的“习”","On its own it leans toward practice/habit; with 学 it makes “to study”.","Em uso solo pende a prática/hábito; com 学 forma “estudar”.","单用偏练习；和“学”组成“学习”。"],["校","xiào","school (in 学校)","escola (em 学校)","学校的“校”","With 学 → school. Tone xiào here, not jiào.","Com 学 → escola. Tom xiào aqui, não jiào.","和学组成学校。这里读 xiào，不读 jiào。"],["见","jiàn","to see; meet (in 见面)","ver; encontrar (em 见面)","看见；见面的“见”","With 面 it means meet in person.","Com 面 vira encontrar alguém ao vivo.","和“面”组成见面。"],["面","miàn","face; surface (in 见面)","rosto; superfície (em 见面)","脸；见面的“面”","In 见面, the “face” you show when you meet.","Em 见面, o “rosto” do encontro.","在“见面”里是碰面的面。"]])}},{id:"hz-lookalikes",name:e("Characters that look alike","Caracteres que se parecem","容易认错的字"),intro:e("A single stroke flips the meaning. Trace both sides, say both sounds, then cover and write from memory. Comparison is the point — not a stroke-order score.","Um traço só troca o sentido. Trace os dois, fale os dois sons, tape e escreva de memória. O ponto é comparar — não nota de ordem dos traços.","多一笔就变义。两边都描、两边都读，再遮住默写。重点是对照，不是笔顺打分。"),quest:e("Write 人 and 入 side by side from memory, then check which stroke leans which way.","Escreva 人 e 入 lado a lado de memória e confira para que lado cada traço inclina.","凭记忆并排写人和入，再看哪一笔往哪边斜。"),pack:{id:"hz-lookalikes",speak:j,hideRoman:!0,recall:"roman",items:c([["人","rén","person","pessoa","人类；一个人","Legs open downward. Contrast 入.","Pernas abertas para baixo. Contraste com 入.","两腿向下分开。对比“入”。"],["入","rù","to enter","entrar","从外到里","Top stroke leans in; looks like a person squeezing through.","O traço de cima inclina para dentro.","上笔往里收，像挤进去。"],["己","jǐ","self (in 自己)","si (em 自己)","自己的“己”","Open on the bottom left. Not 已.","Aberto embaixo à esquerda. Não 已.","左下开口。不是“已”。"],["已","yǐ","already","já","已经","Half-closed. 已经 uses this one.","Meio fechado. 已经 usa este.","半封闭。已经用这个。"],["未","wèi","not yet","ainda não","还没有","Shorter top crossbar than 末.","Trave de cima mais curta que 末.","上横比“末”短。"],["末","mò","end, tip","fim, ponta","末端","Longer top crossbar than 未.","Trave de cima mais longa que 未.","上横比“未”长。"],["买","mǎi","to buy","comprar","花钱得到","Third tone. Contrast 卖.","Terceiro tom. Contraste com 卖.","第三声。对比“卖”。"],["卖","mài","to sell","vender","收钱给出","Fourth tone. Extra component on top vs 买.","Quarto tom. Tem mais em cima que 买.","第四声。比“买”多上头。"],["天","tiān","sky; day","céu; dia","天空；日子","Big horizontal on top. Contrast 夫.","Grande horizontal em cima. Contraste com 夫.","上面一长横。对比“夫”。"],["夫","fū","husband; man (literary)","marido; homem (literário)","丈夫；成年男子","The top stroke sticks out past the verticals.","O traço de cima passa das verticais.","上横伸出两边。"]])}},{id:"hz-hand-speech",name:e("Hand and speech shapes","Formas de mão e de fala","手旁和言旁"),intro:e("扌 often means a hand action; 讠 often means speech. Spot the left side first, then the sound or second half. Write from memory, then reveal.","扌 costuma ser ação da mão; 讠 costuma ser fala. Veja a esquerda primeiro, depois o som ou a outra metade. Escreva de memória e só então revele.","扌多半是手的动作；讠多半和说话有关。先看左边，再看另一半。先默写，再显示。"),quest:e("Find three 扌 characters on any Chinese screen and guess they involve a hand.","Ache três caracteres com 扌 em qualquer tela em chinês e chute que envolvem a mão.","在任何中文屏幕上找三个带扌的字，猜它们和手有关。"),pack:{id:"hz-hand-speech",speak:j,hideRoman:!0,recall:"roman",items:c([["打","dǎ","to hit; to do (with 扌)","bater; fazer (com 扌)","手的动作","Same 打 as in Meaning parts — rewrite locks the radical.","O mesmo 打 de Partes de significado — reescrever fixa o radical.","和表意部件里的“打”相同，再写一遍记牢。"],["找","zhǎo","to look for","procurar","寻找","扌 + 戈. Hand searching.","扌 + 戈. Mão à procura.","扌加戈，像伸手找。"],["报","bào","to report; newspaper","reportar; jornal","告诉；报纸","Hand radical; meaning stretches to news.","Radical da mão; o sentido chega a notícia.","提手旁；引申到报纸新闻。"],["提","tí","to carry; to raise (a point)","carregar; levantar (um ponto)","用手拿起；提出","提出问题: raise a question.","提出问题: levantar uma pergunta.","提出问题。"],["说","shuō","to speak (讠)","falar (讠)","用语言表达","Speech radical on the left.","Radical da fala à esquerda.","左边是言字旁。"],["请","qǐng","please; to invite","por favor; convidar","请求；邀请","请坐 / 请进: soft requests.","请坐 / 请进: pedidos suaves.","请坐、请进。"],["谢","xiè","to thank (in 谢谢)","agradecer (em 谢谢)","表示感谢","Write 谢 twice for 谢谢.","Escreva 谢 duas vezes para 谢谢.","谢谢要写两个谢。"],["话","huà","speech; words","fala; palavras","说的话","说话: to speak. 电话: phone.","说话: falar. 电话: telefone.","说话。电话。"],["认","rèn","to recognize","reconhecer","认出；承认","认识: to know (a person / fact).","认识: conhecer (pessoa / fato).","认识。"],["记","jì","to remember; to write down","lembrar; anotar","记住；记录","记住: remember firmly.","记住: gravar bem.","记住。"]])}},{id:"hz-numbers",name:e("Numbers you will write","Números que você vai escrever","会写的数字"),intro:e("Write the digits you already say in clock and measure floors. Stroke them from memory, then reveal — scenery calligraphy can wait.","Escreva os dígitos que você já fala nos andares de relógio e medida. Trace de memória e só então revele — caligrafia de paisagem pode esperar.","写出你在钟点和量词层已经会说的数字。先默写再显示——风景书法以后再说。"),quest:e("Write today’s date with 年月日 and the digits from memory once.","Escreva a data de hoje com 年月日 e os dígitos, de memória, uma vez.","凭记忆用年月日和数字写一次今天的日期。"),pack:{id:"hz-numbers",speak:j,hideRoman:!0,recall:"roman",items:c([["一","yī","one","um","数目一","Tone often changes before another 4th (一样 yíyàng).","O tom muda antes de outro 4º (一样 yíyàng).","在另一第四声前常变调（一样）。"],["二","èr","two (counting)","dois (contar)","数目二","两 is “two of a measure”; 二 is the digit/name.","两 é “dois de uma medida”; 二 é o dígito/nome.","量词前多用两；读数用二。"],["三","sān","three","três","数目三","三点: three o’clock — AM/PM still open.","三点: três horas — manhã/tarde ainda aberta.","三点：上下午仍要靠语境。"],["四","sì","four","quatro","数目四","Sounds like 死 in some dialects — know the joke, keep the digit.","Soa como 死 em alguns dialetos — conheça a piada, guarde o dígito.","有的方言谐音死——知道梗，数字照写。"],["五","wǔ","five","cinco","数目五","星期五: Friday.","星期五: sexta-feira.","星期五。"],["六","liù","six","seis","数目六","Sixth tone practice: clear falling contour.","Prática do 4º tom: queda clara.","第四声：降得干净。"],["七","qī","seven","sete","数目七","Often yī-like tone sandhi before 4th in compounds.","Às vezes muda como 一 antes de 4º em compostos.","在复合里有时像一一样变调。"],["八","bā","eight","oito","数目八","Lucky number talk is culture; the stroke order is still eight.","Fala de sorte é cultura; a ordem dos traços continua oito.","吉利说法是文化；笔顺仍是八。"],["九","jiǔ","nine","nove","数目九","九月: September.","九月: setembro.","九月。"],["十","shí","ten","dez","数目十","十一 builds eleven: ten + one.","十一 monta onze: dez + um.","十一＝十加一。"],["百","bǎi","hundred","cem","数目百","三百: three hundred.","三百: trezentos.","三百。"],["年","nián","year","ano","年份","2026年 — year after the digits in Chinese dates.","2026年 — o ano depois dos dígitos em datas chinesas.","中文日期里年份在数字后加年。"]])}}],b="zh-CN",le=M("mandarin"),he=[{id:"zh-first",name:e("Survival footing","Base de sobrevivência","先能开口"),intro:e("Floor 0: chantable chunks — greetings, thanks, questions like 多少钱？ and 你好吗？ Learn the whole block, say it out loud (tone included), then prove it from memory. Lone glue words wait upstairs.","Andar 0: blocos pra cantar — cumprimentos, agradecimentos, perguntas tipo 多少钱？ e 你好吗？ Aprenda o bloco inteiro, diga em voz alta (tom incluso) e prove de memória. Cola solta sobe depois.","第0层：能整段念的块——问候、谢谢、多少钱？你好吗？先整块学，大声说（含声调），再凭记忆证明。单字胶水以后再学。"),quest:e("Say 你好吗？ and 谢谢 to anyone today: a friend, a video, your mirror.","Diga 你好吗？ e 谢谢 para alguém hoje: pode ser uma amizade, um vídeo, o espelho.","今天对谁说一句你好吗？和谢谢：朋友、视频、镜子都行。"),pack:le},{id:"zh-questions",name:e("Asking anything","Perguntar qualquer coisa","什么都能问"),intro:e("Good news: in Chinese a question keeps the same word order as the answer. Put the question word where the answer goes. No flipping, no helper verbs.","Boa notícia: em chinês a pergunta mantém a mesma ordem da resposta. Coloque a palavra de pergunta onde a resposta entra. Sem inverter, sem verbo auxiliar.","好消息：中文问句和答句语序相同。答案在哪儿，疑问词就放在哪儿。"),quest:e("Ask yourself three of these questions out loud, then answer in Chinese as far as you can.","Faça três dessas perguntas em voz alta e responda em chinês até onde der.","大声问自己其中三个问题，尽量用中文回答。"),pack:{id:"zh-questions",speak:b,hideRoman:!0,items:c([["什么","shénme","what","o quê","问东西或事情","It goes where the answer goes: 你吃什么?","Vai onde a resposta vai: 你吃什么?","放在答案的位置：你吃什么？"],["谁","shéi","who","quem","问人","No word order change: 他是谁?","A ordem não muda: 他是谁?","语序不变：他是谁？"],["哪里","nǎlǐ","where","onde","问地方","Also a modest reply to a compliment.","Também é uma resposta modesta a um elogio.","也可以用来谦虚地回应夸奖。"],["什么时候","shénme shíhou","when","quando","问时间",'Literally "what time".','Ao pé da letra, "que hora".',"字面意思是“什么时间”。"],["为什么","wèishénme","why","por quê","问原因","Answer with 因为 (because).","Responda com 因为 (porque).","用“因为”来回答。"],["怎么","zěnme","how","como","问方法",'怎么说? means "how do you say it?"','怎么说? quer dizer "como se diz?"',"怎么说？就是问说法。"],["多少","duōshao","how many, how much","quantos, quanto","问数量，常用于较大的数","For bigger numbers and prices.","Para números maiores e preços.","用于较大的数和价格。"],["几","jǐ","how many (small numbers)","quantos (poucos)","问较小的数量","When you expect fewer than about ten.","Quando você espera menos de uns dez.","预计少于十个左右时用。"],["吗","ma","turns a sentence into a yes/no question","transforma a frase em pergunta de sim ou não","放在句尾表示疑问","Add it at the end and nothing else changes.","Coloque no fim e nada mais muda.","加在句尾，其他都不变。"],["呢","ne",'"and you?", "what about...?"','"e você?", "e quanto a...?"',"放在词后，反问同样的问题","我很好，你呢? is the classic.","我很好，你呢? é o clássico.","我很好，你呢？是经典用法。"]])}},{id:"zh-measure",name:e("Measure words","Palavras de medida","量词"),intro:e(`Chinese can't say "two books". It says "two [flat-bound-thing] books". The measure word goes between the number and the noun. 个 works when you forget, but these make you sound fluent.`,'Em chinês não dá para dizer "dois livros". Diz-se "dois [coisa-encadernada] livros". A palavra de medida fica entre o número e o substantivo. 个 salva quando você esquece, mas estas fazem você soar fluente.',"数词和名词之间要放量词。忘了可以用“个”救场，但用对量词才地道。"),quest:e("Point at five things in your room and count them with the right measure word.","Aponte para cinco coisas no seu quarto e conte com a palavra de medida certa.","指着房间里的五样东西，用正确的量词数一数。"),pack:{id:"zh-measure",speak:b,hideRoman:!0,items:c([["个","gè","the general one: people and many things","a geral: pessoas e muitas coisas","最常用的量词","The safe default when you forget.","O padrão seguro quando você esquece.","想不起来时的万能选择。"],["本","běn","for books","para livros","用于书","一本书: one book.","一本书: um livro.","一本书。"],["张","zhāng","for flat things: paper, tables, tickets","para coisas planas: papel, mesas, ingressos","用于平的东西","Think of a flat surface.","Pense em uma superfície plana.","想想平面的东西。"],["杯","bēi","for cups and glasses of something","para copos e xícaras de algo","用于一杯水、一杯茶","一杯咖啡: a cup of coffee.","一杯咖啡: um café.","一杯咖啡。"],["一只","yì zhī","for many small animals: one of them","para muitos animais pequenos: um deles","用于小动物，比如一只猫","一只猫: one cat.","一只猫: um gato.","小猫小狗都用它。"],["件","jiàn","for clothes on the upper body, and matters","para roupas da parte de cima, e assuntos","用于上衣和事情","一件事: one matter.","一件事: um assunto.","一件事。"],["条","tiáo","for long thin things: roads, rivers, trousers","para coisas longas e finas: ruas, rios, calças","用于长条形的东西","一条路: one road.","一条路: uma rua.","一条路。"],["辆","liàng","for vehicles","para veículos","用于车","一辆车: one car.","一辆车: um carro.","一辆车。"],["位","wèi","for people, politely","para pessoas, com educação","礼貌地用于人","Restaurant staff ask 几位? (how many of you?)","No restaurante perguntam 几位? (quantas pessoas?)","餐厅会问：几位？"],["瓶","píng","for bottles","para garrafas","用于瓶装的东西","一瓶水: a bottle of water.","一瓶水: uma garrafa de água.","一瓶水。"]])}},{id:"zh-verbs",name:e("Verbs you use all day","Verbos do dia todo","每天都用的动词"),intro:e("Chinese verbs never change: no conjugation, no tenses to memorize. 我吃, 你吃, 他吃. Learn each one once and it works forever.","Verbos chineses nunca mudam: sem conjugação, sem tempos para decorar. 我吃, 你吃, 他吃. Aprenda uma vez e funciona para sempre.","中文动词不变形：我吃、你吃、他吃。学一次，一直能用。"),quest:e("Describe your day out loud using at least four of these verbs.","Descreva o seu dia em voz alta usando pelo menos quatro destes verbos.","用至少四个动词大声描述你的一天。"),pack:{id:"zh-verbs",speak:b,hideRoman:!0,items:c([["吃","chī","to eat","comer","把食物放进嘴里",'吃饭 means "to have a meal".','吃饭 quer dizer "fazer uma refeição".',"吃饭就是用餐。"],["喝","hē","to drink","beber","把水等咽下去","喝水: drink water.","喝水: beber água.","喝水。"],["看","kàn","to look, watch, read","olhar, assistir, ler","用眼睛","One verb covers TV, books and people.","Um verbo só para TV, livro e pessoas.","电视、书、人都能用它。"],["听","tīng","to listen","ouvir","用耳朵",'听懂 means "to understand by listening".','听懂 quer dizer "entender de ouvido".',"听懂是听了能明白。"],["说","shuō","to speak, to say","falar, dizer","用嘴表达","说中文: speak Chinese.","说中文: falar chinês.","说中文。"],["买","mǎi","to buy","comprar","花钱得到东西",'Third tone. Fourth tone 卖 (mài) means "to sell". The tone decides who pays.','Terceiro tom. O quarto tom 卖 (mài) é "vender". O tom decide quem paga.',"第三声。第四声的“卖”是相反的意思。声调决定谁付钱。"],["去","qù","to go","ir","离开这里到别处","The place follows directly: 我去北京.","O lugar vem direto: 我去北京.","地点直接跟在后面：我去北京。"],["来","lái","to come","vir","从别处到这里","Opposite of 去, toward the speaker.","O oposto de 去, na direção de quem fala.","和“去”相反，朝说话人的方向。"],["想","xiǎng","to want; to think; to miss","querer; pensar; sentir saudade","有愿望；思考；思念","想 is softer than 要.","想 é mais suave que 要.","“想”比“要”委婉。"],["要","yào","to want, to need, will","querer, precisar, ir (fazer)","明确需要",`Firm: 我要这个 means "I'll take this one".`,'Firme: 我要这个 é "vou querer este".',"语气坚定：我要这个。"],["有","yǒu","to have; there is","ter; haver","拥有；存在","The negative is 没有, never 不有.","A negação é 没有, nunca 不有.","否定是“没有”，不说“不有”。"],["是","shì","to be (joining two nouns)","ser (ligando dois substantivos)","说明两者相等","Not with adjectives: 我很好, never 我是好.","Não com adjetivos: 我很好, nunca 我是好.","不和形容词连用：说我很好，不说我是好。"]])}},{id:"zh-study-meet",name:e("Arranging a study session","Combinar um horário de estudo","约个学习时间"),intro:e("Pattern: 我们 + day + time + 一起 + verb, 可以吗？ Worked example — A: 我们明天三点一起学习，可以吗？ B: 可以！我去学校。 Say your own version out loud before you peek at the list. Pinyin stays hidden until you ask.","Padrão: 我们 + dia + hora + 一起 + verbo, 可以吗？ Exemplo — A: 我们明天三点一起学习，可以吗？ B: 可以！我去学校。 Fale a sua versão em voz alta antes de olhar a lista. O pinyin fica escondido até você pedir.","句型：我们 + 日子 + 时间 + 一起 + 动词，可以吗？示范 — A：我们明天三点一起学习，可以吗？ B：可以！我去学校。先自己大声说一句，再看词表。拼音先藏着。"),quest:e("Text a friend (or yourself) one real invite in Chinese using today or tomorrow and a clock time.","Mande para alguém (ou para você) um convite real em chinês com hoje ou amanhã e um horário.","用中文给朋友（或自己）发一条真实邀约：今天或明天，加上钟点。"),pack:{id:"zh-study-meet",speak:b,hideRoman:!0,items:c([["今天","jīntiān","today","hoje","说话时的这一天","Not “this day” word by word — one chunk.","Não é “este” + “dia” separado: é um bloco.","不是“今”加“天”硬拼，当一个词记。"],["明天","míngtiān","tomorrow","amanhã","今天的下一天","Same chunk pattern as 今天.","Mesmo padrão de 今天.","和“今天”同一类。"],["点","diǎn","o’clock (after a number)","hora (depois do número)","用在数字后表示钟点","三点 = 3:00 (three o’clock). It does not pick AM or PM by itself — add 下午 for afternoon.","三点 = 3h (três horas). Por si não escolhe manhã ou tarde — diga 下午 se for à tarde.","三点就是3点，本身不分上下午。要说下午就加“下午”。"],["半","bàn","half (past the hour)","meia (hora)","整点后再过半小时","三点半 = 3:30. It follows the hour, never “half three” first.","三点半 = 3h30. Vem depois da hora, não antes.","三点半。半在点后面。"],["一起","yìqǐ","together","juntos","和别人同时做","Citation spelling yìqǐ (一 already changed before 起). Say 我们一起学习 with that reading — not isolation yī.","Grafia de citação yìqǐ (一 já mudou antes de 起). Em 我们一起学习 use essa leitura — não o yī isolado.","词典常标 yìqǐ（“一”在“起”前已变调）。说我们一起学习用这个读法，不是单念的 yī。"],["学习","xuéxí","to study, to learn","estudar, aprender","有意地学东西","学习 is the everyday two-syllable verb. 学中文 is also fine: 学 can take a subject.","学习 é o verbo corrente de duas sílabas. 学中文 também vale: 学 pode levar um assunto.","“学习”是常用双音动词。学中文也成立：单说“学”可以带宾语。"],["可以","kěyǐ","can; may; “sure”","poder; “pode ser”","表示允许或同意","可以吗？ softens a request. 可以！ alone means “sure”.","可以吗？ suaviza o pedido. Só 可以！ já é “pode / beleza”.","可以吗？用来商量。单独说可以！就是答应。"],["学校","xuéxiào","school","escola","学生学习的地方","我去学校: I’m going to school. Place follows 去 directly.","我去学校: vou à escola. O lugar vem logo após 去.","我去学校。地点紧跟“去”。"],["见面","jiànmiàn","to meet (in person)","encontrar-se (ao vivo)","人和人碰面","We 见面; we don’t 看 a person for “meet up”.","A gente 见面; não se usa 看 para “encontrar alguém”.","约人用见面，不用看。"],["时间","shíjiān","time (as a span or schedule)","tempo, horário","一段时间或安排的时刻","什么时间？ asks when. Different from 点 (clock reading).","什么时间？ pergunta quando. Diferente de 点 (leitura do relógio).","什么时间？问何时。和“点”的钟点读法不同。"]])}},{id:"zh-numbers",name:e("Numbers and clock time","Números e horas","数字和钟点"),intro:e("Chinese counts in tens and builds clock time as number + 点. Learn 1–10 solid, then 十一 and 二十 ride on that. Say each number with its tone before you check.","O chinês conta de dez em dez e monta a hora como número + 点. Firme 1–10; 十一 e 二十 vêm em cima disso. Fale cada número com o tom antes de conferir.","中文用十进制，钟点是数字加“点”。先把1到10说稳，十一、二十就好办。先连声调说出来，再核对。"),quest:e("Say today’s date and the next hour out loud in Chinese.","Fale em voz alta a data de hoje e a próxima hora cheia em chinês.","用中文大声说出今天的日期和下一个整点。"),pack:{id:"zh-numbers",speak:b,hideRoman:!0,items:c([["一","yī","one","um","最小的整数之一","Before a 4th-tone syllable it often sounds like yí (一碗).","Antes de uma sílaba de 4º tom costuma soar yí (一碗).","在第四声前常读成 yí，如一碗。"],["二","èr","two (counting, math)","dois (contagem, matemática)","计数时的“二”","For “two of a thing” people often say 两 + measure: 两个.","Para “dois de algo” costuma-se 两 + medida: 两个.","说“两个”更常；计数、数学多用二。"],["两","liǎng","two (with a measure word)","dois (com palavra de medida)","和量词搭配的“两”","两本书, not 二本书 in everyday speech.","两本书, não 二本书 no dia a dia.","口语说两本书，少说二本书。"],["三","sān","three","três","数目三","First tone. Keep it flat.","Primeiro tom. Mantenha plano.","第一声，平。"],["五","wǔ","five","cinco","数目五","Third tone: dip, then rise when alone.","Terceiro tom: desce e sobe na forma isolada.","第三声，单念先降后升。"],["十","shí","ten","dez","数目十","十一 = 10+1. 二十 = 2×10.","十一 = 10+1. 二十 = 2×10.","十一是10加1；二十是两个十。"],["百","bǎi","hundred","cem","数目一百","三百 = 300. Zero in the middle needs 零: 一百零五.","三百 = 300. Zero no meio pede 零: 一百零五.","三百。中间有零要说：一百零五。"],["点","diǎn","o’clock (after a number)","hora (depois do número)","用在数字后表示钟点","五点 = 5:00. Same 点 as in the study-meet tier.","五点 = 5h. O mesmo 点 do nível de combinar estudo.","五点。和约学习那一层的“点”相同。"],["分","fēn","minute (after a number)","minuto (depois do número)","用在数字后表示分钟","五点十分 = 5:10. Optional in casual speech for :00.","五点十分 = 5h10. Em fala casual, :00 às vezes some.","五点十分。整点口语里有时省略分。"],["现在","xiànzài","now","agora","说话的这个时候","现在几点？ asks the clock time.","现在几点？ pergunta as horas.","现在几点？问钟点。"],["早上","zǎoshang","morning","de manhã","一天的上午较早时","Often with 在: 在早上… or just 早上…","Costuma com 在: 在早上… ou só 早上…","可说在早上，也可直接早上。"],["晚上","wǎnshang","evening / night","à noite","天黑以后","晚上见: see you tonight.","晚上见: até à noite.","晚上见。"]])}},{id:"zh-pronouns",name:e("People words","Palavras de pessoa","人称代词"),intro:e("我 / 你 / 他 / 她 / 我们. Add 的 for possession: 我的书. Chinese does not change these for subject vs object — 我 likes 我.","我 / 你 / 他 / 她 / 我们. Some 的 para posse: 我的书. Em chinês não mudam de sujeito para objeto — 我 gosta de 我.","我、你、他、她、我们。加“的”表所属：我的书。主语宾语同形。"),quest:e("Point at three people (or photos) and name them with 他 / 她 / 他们 out loud.","Aponte para três pessoas (ou fotos) e nomeie com 他 / 她 / 他们 em voz alta.","指着三个人（或照片），用他 / 她 / 他们大声说。"),pack:{id:"zh-pronouns",speak:b,hideRoman:!0,items:c([["我","wǒ","I, me","eu, me","说话的人自己","Same form as object: 他看我.","Mesma forma como objeto: 他看我.","作宾语也是我：他看我。"],["你","nǐ","you (singular)","você (uma pessoa)","对方一个人","你们 is plural you.","你们 é o plural.","复数是你们。"],["他","tā","he, him","ele","男性的那个人","Spoken tā is the same as 她 / 它 — writing carries the gender.","Falado tā é igual a 她 / 它 — a escrita carrega o gênero.","口语都是 tā；阴阳性写出来才分。"],["她","tā","she, her","ela","女性的那个人","Same spoken syllable as 他.","Mesma sílaba falada que 他.","读音和“他”一样。"],["我们","wǒmen","we, us","nós","说话人一方的一群人","Inclusive “we” in most everyday talk.","O “nós” do dia a dia.","日常里的“我们”。"],["他们","tāmen","they (mixed or male group)","eles (grupo misto ou masculino)","那些人","Writing often uses 他们 for mixed groups.","Na escrita, grupos mistos costumam 他们.","混用的群体常写他们。"],["的","de","possessive / descriptor linker","liga dono ou descrição","连接所属或修饰","我的书: my book. Also links descriptions: 红色的车.","我的书: meu livro. Também liga descrição: 红色的车.","我的书。也可说红色的车。"],["这","zhè","this","isto, este","离说话人近的","Often 这个 + noun.","Costuma 这个 + substantivo.","常说这个加名词。"],["那","nà","that","aquilo, aquele","离说话人远的","那个 vs 这 — distance from the speaker.","那个 vs 这 — distância de quem fala.","那个和这相对，远近不同。"],["谁","shéi","who","quem","问人","Same word as in Asking anything; here as a pronoun answer slot.","A mesma de Perguntar; aqui como slot de resposta.","和“什么都能问”里相同，这里当代词用。"],["自己","zìjǐ","oneself","a si; a própria pessoa","指本人","我自己: I myself. Soft emphasis, not guilt.","我自己: eu, por mim. Ênfase suave, sem culpa.","我自己。加重语气，不是责怪。"],["大家","dàjiā","everyone","todo mundo","所有相关的人","大家好 is the room greeting.","大家好 é a saudação da sala.","大家好是招呼全场。"]])}},{id:"zh-particles",name:e("Little words that change the sentence","Palavrinhas que mudam a frase","改变句子的小品词"),intro:e("了, 的, 过, 着 sit after verbs or nouns and shift time, possession or aspect. Wrong ones are real learner traps, not jokes.","了, 的, 过, 着 vêm depois de verbos ou nomes e mudam tempo, posse ou aspecto. Os erros abaixo são armadilhas reais, não piada.","了、的、过、着跟在动词或名词后，改变时间、所属或状态。下面的错法是真误会，不是笑话。"),quest:e("Take one thing you did today and say it once with 了 and once with 过 — notice the feel.","Pegue uma coisa que você fez hoje e diga uma vez com 了 e uma com 过 — sinta a diferença.","用今天做的一件事，分别用了和过说一遍，体会差别。"),pack:{id:"zh-particles",speak:b,hideRoman:!0,items:c([["了","le","marks a change or completed event","marca mudança ou evento concluído","表示变化或完成","我吃了: I ate / I’ve eaten (relevant now). Not past tense glue on every verb.","我吃了: comi / já comi (vale agora). Não é passado em todo verbo.","我吃了。不是每个动词都要加的“过去时”。"],["的","de","links a description or owner","liga descrição ou dono","连接修饰或所属","Same 的 as possession. 红的 vs 红了 are different jobs.","O mesmo 的 de posse. 红的 e 红了 são funções diferentes.","和所属的“的”相同。红的和红了不是一回事。"],["过","guo","have ever done (experience)","já ter feito (experiência)","表示经历","我去过北京: I’ve been to Beijing (at some point). Not “I went today”.","我去过北京: já estive em Pequim. Não é “fui hoje”.","我去过北京。不是“今天去了”。"],["着","zhe","ongoing state / result held","estado contínuo / resultado mantido","表示持续的状态","门开着: the door is open (and stays so).","门开着: a porta está aberta (e segue).","门开着。门保持开着。"],["吗","ma","yes/no question ending","fim de pergunta sim/não","句尾疑问","Statement + 吗. Word order stays.","Afirmação + 吗. A ordem fica.","陈述句加吗，语序不变。"],["呢","ne","and…? / what about…?","e…? / e quanto a…?","追问同样的问题","你呢? after sharing about yourself.","你呢? depois de falar de si.","介绍完自己再问你呢？"],["吧","ba","soft suggestion / confirmation","sugestão suave / confirmação","商量或确认","走吧: let’s go (shall we?).","走吧: vamos? (sugestão).","走吧。带商量口气。"],["啊","a","softens or livens the tone","ameniza ou anima o tom","缓和或加强语气","Tone follows the mood; don’t overuse in formal writing.","O tom segue o clima; em texto formal, use pouco.","语气词。正式书写少用。"],["地","de","turns an adjective into an adverb","transforma adjetivo em advérbio","形容词后，修饰动词","高兴地说: said happily. Different character from possessive 的.","高兴地说: disse alegremente. Caractere diferente do 的 de posse.","高兴地说。和所属的“的”不是同一个字。"],["得","de","links verb to how well / result","liga verbo a como / resultado","动词后，表示程度或结果","说得很好: speaks very well. Third 的/地/得 trap.","说得很好: fala muito bem. A terceira armadilha 的/地/得.","说得很好。的地得里的第三个。"],["在","zài"," Progressive “be doing”; also location","“estar fazendo”; também lugar","正在做；也表示处所","我在学习: I’m studying. 在学校: at school.","我在学习: estou estudando. 在学校: na escola.","我在学习。在学校是处所。"],["没","méi","negates 有 and past events","nega 有 e eventos passados","否定“有”和过去发生","没去: didn’t go. With 有 → 没有. Not 不有.","没去: não fui. Com 有 → 没有. Não 不有.","没去。有的否定是没有。"]])}},{id:"zh-food",name:e("Food and buying things","Comida e compras","吃饭和买东西"),intro:e("Restaurant and shop Chinese is short: 要 / 买 + measure + thing. Prices ride 多少钱. Order out loud before you peek.","Chinês de restaurante e loja é curto: 要 / 买 + medida + coisa. Preço com 多少钱. Peça em voz alta antes de olhar.","点餐购物很短：要 / 买 + 量词 + 东西。问价用多少钱。先大声说，再看词。"),quest:e("Order an imaginary meal with three of these lines, then check the list.","Peça uma refeição imaginária com três destas falas e confira a lista.","用其中三句点一餐想象中的饭，再对照词表。"),pack:{id:"zh-food",speak:b,hideRoman:!0,items:c([["吃饭","chī fàn","to have a meal","fazer uma refeição","吃一顿饭","Literally “eat rice”; means eating a meal.","Ao pé da letra “comer arroz”; significa fazer uma refeição.","字面是吃饭，实际指用餐。"],["菜单","càidān","menu","cardápio","列菜名的单子","Ask 有菜单吗？ if none is on the table.","Pergunte 有菜单吗？ se não tiver na mesa.","桌上没有就问：有菜单吗？"],["多少钱","duōshao qián","how much (money)?","quanto custa?","问价格","钱 is money. Don’t drop it when asking price.","钱 é dinheiro. Não omita ao perguntar o preço.","问价要带“钱”。"],["便宜","piányi","cheap, inexpensive","barato","价格低","Second syllable is neutral in everyday speech.","A segunda sílaba é neutra no dia a dia.","口语里第二音节常轻声。"],["贵","guì","expensive","caro","价格高","太贵了: too expensive.","太贵了: caro demais.","太贵了。"],["水","shuǐ","water","água","喝的水","一杯水 with the cup measure.","一杯水 com a medida de copo.","说一杯水。"],["茶","chá","tea","chá","茶水","中国茶 vs 奶茶 — say which you mean.","中国茶 vs 奶茶 — diga qual.","说清是中国茶还是奶茶。"],["咖啡","kāfēi","coffee","café","咖啡饮品","Loanword; tones still matter.","Empréstimo; os tons ainda importam.","外来词，声调仍要准。"],["米饭","mǐfàn","cooked rice","arroz (cozido)","煮熟的米","饭 alone can mean “meal”; 米饭 is the grain.","Só 饭 pode ser “refeição”; 米饭 é o grão.","单说饭可指一餐；米饭是米本身。"],["肉","ròu","meat","carne","食用的肉","Specify: 鸡肉, 牛肉…","Especifique: 鸡肉, 牛肉…","要说清鸡肉、牛肉等。"],["蔬菜","shūcài","vegetables","verduras, legumes","可吃的菜蔬","菜 alone can mean dish or vegetables by context.","Só 菜 pode ser prato ou verdura, pelo contexto.","单说菜可指菜品或蔬菜。"],["买单","mǎidān","to ask for the bill","pedir a conta","结账","Also 买单！ to the staff. Not 买菜单.","Também 买单！ para a equipe. Não 买菜单.","对店员说买单。不是买菜单。"]])}},{id:"zh-place",name:e("Where things are","Onde as coisas ficam","东西在哪儿"),intro:e("Getting around is chunks: 在哪儿？ + left/right/ahead + 怎么走？ Say the whole line before you peek. Glue from earlier floors does the work inside.","Se locomover é em blocos: 在哪儿？ + esquerda/direita/à frente + 怎么走？ Diga a linha inteira antes de olhar. A cola dos andares de baixo faz o trabalho por dentro.","找路靠整块：在哪儿？+ 左/右/前面 + 怎么走？先整句说，再看词。下面几层的胶水在句子里干活。"),quest:e("Ask 在哪儿？ about three real places near you (shop, bathroom, stop), out loud.","Pergunte 在哪儿？ sobre três lugares reais perto de você (loja, banheiro, ponto), em voz alta.","大声对身边三个真实地点问在哪儿？（店、厕所、车站都行）。"),pack:{id:"zh-place",speak:b,hideRoman:!0,items:c([["在哪儿？","zài nǎr","where is it?","onde fica?","问位置","儿化 is common; 在哪里？ is the same job.","儿化 é comum; 在哪里？ é o mesmo trabalho.","常儿化；在哪里？同功用。"],["左边","zuǒbiān","left side","lado esquerdo","靠左","往左边走: go left.","往左边走: vá à esquerda.","往左边走。"],["右边","yòubiān","right side","lado direito","靠右","Mirror of 左边.","Espelho de 左边.","和左边相对。"],["前面","qiánmiàn","in front / ahead","na frente","在前方","Also “the front of…”.","Também “a frente de…”.","也可说某物的前面。"],["后面","hòumiàn","behind / at the back","atrás","在后方","Pairs with 前面.","Par com 前面.","和前面成对。"],["怎么走？","zěnme zǒu","how do I get there?","como eu chego?","问路","After a place: 车站怎么走？","Depois do lugar: 车站怎么走？","地名后：车站怎么走？"],["近","jìn","near / close","perto","距离短","很近: very close.","很近: bem perto.","很近。"],["远","yuǎn","far","longe","距离长","不远: not far — a useful softener.","不远: não é longe — suaviza.","不远：常用缓和说法。"],["一直走","yìzhí zǒu","go straight","siga em frente","不要转弯地走","A direction chunk, not lone 直.","Bloco de direção, não 直 isolado.","整块方向语，不是单说直。"],["拐弯","guǎiwān","to turn (a corner)","fazer a curva","改变方向","左拐 / 右拐 in speech.","左拐 / 右拐 na fala.","口语常说左拐、右拐。"],["路口","lùkǒu","intersection","cruzamento","路与路相交处","下一个路口: at the next junction.","下一个路口: no próximo cruzamento.","下一个路口。"],["对面","duìmiàn","across from / opposite","do outro lado / em frente","正对着的那边","银行在对面.","银行在对面.","银行在对面。"]])}}],pe=M("programming"),p=(a,t,s,r,o)=>[a,t,t,t,s,r,o],ge=[{id:"code-words",name:e("The words","As palavras","基本词汇"),intro:e("Floor 0: the search terms that unstick you — variable, loop, function, bug. Fancy patterns wait until you can read a line out loud.","Andar 0: as palavras de busca que te tiram do beco — variável, laço, função, bug. Padrão sofisticado espera você ler uma linha em voz alta.","第0层：卡住时能搜的词——变量、循环、函数、bug。花哨写法等你能大声读懂一行再说。"),quest:e("Explain one of these words to someone, or to a rubber duck, out loud.","Explique uma dessas palavras para alguém, ou para um pato de borracha, em voz alta.","把其中一个词讲给别人或小黄鸭听，要说出声。"),pack:pe},{id:"code-predict",name:e("Predict the output","Preveja o resultado","预测输出"),intro:e("Before you write code, you read it. See a line, say what the computer will do, exactly. This is the skill that separates people who guess from people who know.","Antes de escrever código, você lê. Veja a linha e diga exatamente o que o computador vai fazer. É a habilidade que separa quem chuta de quem sabe.","写代码之前先读代码。看到一行，准确说出计算机会做什么。这就是“猜”和“懂”的分界。"),quest:e("Open a Python console and test three of these, plus one you invent. Were you right?","Abra um console de Python e teste três destes, mais um que você inventar. Acertou?","打开 Python 控制台，试其中三个，再加一个你自己编的。猜对了吗？"),pack:{id:"code-predict",recall:"meaning",items:ne([p("print(2 + 3 * 4)","14","Multiplication comes before addition.","Multiplicação vem antes da soma.","先乘后加。"),p('print("2" + "3")',"23","Text joins text. No math happens.","Texto junta com texto. Nenhuma conta acontece.","文字和文字拼接，不做运算。"),p('print(len("hello"))',"5","len counts the characters.","len conta os caracteres.","len 算的是字符个数。"),p("print(list(range(3)))","[0, 1, 2]","range stops before the number you give it.","range para antes do número que você dá.","range 不包含给定的那个数。"),p("print(10 / 2)","5.0","A single slash always gives a decimal number.","Uma barra só sempre dá número decimal.","单斜杠总是得到小数。"),p("print(7 // 2)","3","Two slashes drop the decimals.","Duas barras descartam os decimais.","双斜杠舍去小数部分。"),p("print(7 % 2)","1","Percent gives the remainder.","O por cento dá o resto da divisão.","百分号是取余数。"),p('print("ab" * 2)',"abab","Multiplying text repeats it.","Multiplicar texto repete o texto.","文字相乘就是重复。"),p("print([4, 5, 6][0])","4","Counting starts at zero.","A contagem começa do zero.","从 0 开始数。"),p('print("hello"[-1])',"o","Negative positions count from the end.","Posições negativas contam do fim.","负数位置从末尾算起。"),p("print(bool(0))","False","Zero and empty things count as False.","Zero e coisas vazias contam como False.","0 和空的东西都算 False。"),p("print(3 == 3.0)","True","Same value, even with different number types.","Mesmo valor, ainda que com tipos de número diferentes.","数值相同，类型不同也相等。")])}},{id:"code-structures",name:e("Where data lives","Onde os dados moram","数据放在哪里"),intro:e("Most problems get easy once the data is in the right container. Choosing the container is most of the design.","A maioria dos problemas fica fácil quando os dados estão no recipiente certo. Escolher o recipiente é a maior parte do projeto.","数据放进合适的容器，大多数问题就变简单了。选容器就是设计的大半。"),quest:e("Think of an app you use daily. Which of these would hold its contacts or messages, and why?","Pense em um app que você usa todo dia. Qual destes guardaria os contatos ou mensagens, e por quê?","想一个你每天用的 App。它的联系人或消息该放进哪种结构？为什么？"),pack:{id:"code-structures",items:v([["List","Lista","列表","An ordered row of items you find by position","Uma fila ordenada de itens que você acha pela posição","有顺序的一排元素，按位置查找","Great for order. Slow when you must search through all of it.","Ótima para ordem. Lenta quando precisa procurar em tudo.","适合保持顺序；要全部翻找时就慢了。"],["Dictionary","Dicionário","字典","Pairs of key and value, found instantly by key","Pares de chave e valor, achados na hora pela chave","键值对，用键立刻找到","Use it when you look things up by name.","Use quando você busca coisas pelo nome.","按名字查东西时用它。"],["Set","Conjunto","集合","A collection with no duplicates and no order","Uma coleção sem repetidos e sem ordem","没有重复、没有顺序的集合",'The quickest way to ask "have I seen this before?"','O jeito mais rápido de perguntar "já vi isso?"',"判断“见过没有”最快的办法。"],["Tuple","Tupla","元组","A fixed group of values that cannot be changed","Um grupo fixo de valores que não pode mudar","固定一组、不能修改的值","Good for things that belong together, like a coordinate.","Boa para coisas que andam juntas, como uma coordenada.","适合成组的数据，比如坐标。"],["Stack","Pilha","栈","Last in, first out, like a pile of plates","Último a entrar, primeiro a sair, como pratos um sobre o outro","后进先出，像一摞盘子","Undo buttons work this way.","O botão de desfazer funciona assim.","撤销按钮就是这样工作的。"],["Queue","Fila","队列","First in, first out, like a line at the bakery","Primeiro a entrar, primeiro a sair — a ordem do atendimento na padaria","先进先出，像面包店排队","Print jobs and message systems work this way.","Impressão e mensagens usam essa ordem.","打印任务和消息系统就是这样。"],["Index","Índice","索引","The position of an item, counted from zero","A posição de um item, contada a partir do zero","元素的位置，从 0 开始数","Off-by-one errors live here.",'O erro de "um a mais" mora aqui.',"差一错误就住在这里。"],["Key","Chave","键","The name you use to find a value","O nome usado para achar um valor","用来查找值的名字","Keys must be unique inside a dictionary.","Chaves não se repetem dentro de um dicionário.","字典里的键不能重复。"],["Immutable","Imutável","不可变","It cannot be changed after it is created","Não pode ser alterado depois de criado","创建之后就不能改",'Text in Python works this way: "changing" it makes a new one.','Texto em Python é assim: "mudar" cria outro.',"Python 的字符串就是这样：“修改”其实是新建。"],["Reference","Referência","引用","A name pointing at data, not a copy of it","Um nome apontando para o dado, não uma cópia","指向数据的名字，不是副本","Two names, one list: change it through one and both see it.","Dois nomes, uma lista: mude por um e os dois veem.","两个名字一个列表：改一处，两边都变。"]])}},{id:"code-thinking",name:e("Fast and slow","Rápido e lento","快与慢"),intro:e("A faster computer can't rescue a bad method. What matters is how the work grows when the data grows. That is all big-O means.","Computador mais rápido não salva um método ruim. O que importa é como o trabalho cresce quando os dados crescem. Big-O é só isso.","再快的电脑也救不了糟糕的方法。关键是数据变多时工作量怎么增长。大 O 说的就是这个。"),quest:e("Look for a word in a physical dictionary or phone book, and notice you are doing binary search.","Procure uma palavra em um dicionário de papel e repare que você está fazendo busca binária.","在纸质词典里查个词，注意你其实在做二分查找。"),pack:{id:"code-thinking",choiceOnly:!0,items:v([["O(1)","O(1)","O(1)","The same work no matter how much data there is","O mesmo trabalho, não importa quantos dados","无论数据多少，工作量都一样","Looking up a dictionary key.","Buscar uma chave em um dicionário.","比如查字典的键。"],["O(n)","O(n)","O(n)","Twice the data, twice the work","O dobro de dados, o dobro de trabalho","数据翻倍，工作量翻倍","Going through a list once.","Passar por uma lista uma vez.","比如遍历一次列表。"],["O(log n)","O(log n)","O(log n)","Twice the data, one extra step","O dobro de dados, um passo a mais","数据翻倍，只多一步","Halving the search each time. A billion items take about 30 steps.","Cortar a busca pela metade a cada vez. Um bilhão de itens leva uns 30 passos.","每次减半。十亿个元素约 30 步。"],["O(n²)","O(n²)","O(n²)","Twice the data, four times the work","O dobro de dados, quatro vezes o trabalho","数据翻倍，工作量变四倍","A loop inside a loop. Fine small, painful big.","Laço dentro de laço. Tranquilo em pequena escala, doloroso em grande.","循环套循环。数据少没事，数据多要命。"],["Binary search","Busca binária","二分查找","Halving a sorted list until you find the item","Cortar uma lista ordenada ao meio até achar o item","不断对半切有序列表，直到找到","It only works if the list is sorted.","Só funciona se a lista estiver ordenada.","前提是列表已排序。"],["Linear search","Busca linear","线性查找","Checking every item one by one","Checar item por item","一个一个地检查","Simple, and fine for short lists.","Simples, e serve para listas curtas.","简单，短列表够用。"],["Recursion","Recursão","递归","A function that calls itself on a smaller problem","Uma função que chama a si mesma com um problema menor","函数调用自身去解决更小的问题","To understand recursion, see: recursion.","Para entender recursão, veja: recursão.","想理解递归，请看：递归。"],["Base case","Caso base","基本情况","The condition that stops a recursion","A condição que para a recursão","让递归停下来的条件","Forget it and the program runs until it crashes.","Esqueça e o programa roda até quebrar.","忘了它，程序会一直跑到崩溃。"],["Hash","Hash","哈希","Turning a key into a position, so lookups are instant","Transformar a chave em uma posição, para buscar na hora","把键变成位置，实现即时查找","This is the trick behind dictionaries and sets.","É o truque por trás de dicionários e conjuntos.","这是字典和集合背后的技巧。"],["Trade-off","Trade-off","权衡","Gaining speed by spending memory, or the reverse","Ganhar velocidade gastando memória, ou o contrário","用内存换速度，或者反过来","There is rarely a free win. Say what you are giving up.","Raramente há ganho de graça. Diga do que está abrindo mão.","很少有白来的好处。说清楚你放弃了什么。"]])}},{id:"code-git",name:e("Git, your undo button","Git, seu botão de desfazer","Git，你的撤销键"),intro:e("Git keeps every version of your work, so a mistake costs minutes, not days. A handful of words covers most of what you will ever do with it.","O Git guarda cada versão do seu trabalho, então um erro custa minutos, não dias. Poucas palavras cobrem quase tudo que você vai fazer com ele.","Git 保存你工作的每个版本，所以出错只损失几分钟，不是几天。几个词就能覆盖大部分操作。"),quest:e("Make a folder, run git init, commit a file, change it, and read the git diff.","Crie uma pasta, rode git init, faça commit de um arquivo, mude ele e leia o git diff.","建个文件夹，运行 git init，提交一个文件，改一改，再看 git diff。"),pack:{id:"code-git",items:v([["Commit","Commit","提交","A saved snapshot of your project, with a message","Uma foto salva do projeto, com uma mensagem","项目的一次快照，附带说明","Small commits make mistakes easy to undo.","Commits pequenos deixam os erros fáceis de desfazer.","小步提交，出错容易撤销。"],["Branch","Branch","分支","A separate line of work that does not touch the main one","Uma linha de trabalho separada, que não mexe na principal","不影响主线的独立工作线","Try things freely, and merge only what works.","Experimente à vontade e junte só o que funcionar.","放心尝试，只合并有用的。"],["Merge","Merge","合并","Bringing one branch's changes into another","Trazer as mudanças de uma branch para outra","把一个分支的改动并入另一个","Git does most of it by itself.","O Git faz a maior parte por conta própria.","Git 能自动完成大部分。"],["Merge conflict","Conflito","合并冲突","Two changes to the same lines that Git can't choose between","Duas mudanças nas mesmas linhas que o Git não consegue escolher","同一处有两个改动，Git 无法决定","Not an error. It is Git asking you a question.","Não é erro. É o Git fazendo uma pergunta.","不是错误，是 Git 在问你。"],["Push","Push","推送","Sending your commits to the remote copy","Enviar seus commits para a cópia remota","把提交发送到远程仓库","Until you push, it exists only on your computer.","Até dar push, só existe no seu computador.","推送之前，它只在你电脑上。"],["Pull","Pull","拉取","Getting the latest commits from the remote copy","Trazer os commits mais recentes da cópia remota","从远程取回最新的提交","Pull before you start, to avoid conflicts later.","Dê pull antes de começar, para evitar conflito depois.","开工前先拉取，减少冲突。"],["Diff","Diff","差异","The exact lines that changed","As linhas exatas que mudaram","具体改动了哪些行","Read it before you commit. Read it twice if an AI wrote it.","Leia antes do commit. Duas vezes se foi uma IA que escreveu.","提交前先看。AI 写的看两遍。"],["Clone","Clone","克隆","Making your own full copy of a repository","Fazer sua própria cópia completa de um repositório","把整个仓库复制一份到本地","You get the whole history, not only the latest files.","Você recebe o histórico inteiro, não só os arquivos atuais.","连完整历史一起拿到。"],["Revert","Revert","回退","A new commit that undoes an old one","Um commit novo que desfaz um antigo","用新提交撤销旧提交","Safe: the history stays honest.","Seguro: o histórico continua honesto.","安全，历史记录依然真实。"],[".gitignore",".gitignore",".gitignore","The list of files Git must never track","A lista de arquivos que o Git nunca deve rastrear","Git 永远不跟踪的文件清单","Keys and passwords belong in it, before the first commit.","Chaves e senhas entram aqui, antes do primeiro commit.","密钥和密码要在第一次提交前放进去。"]])}},{id:"code-errors",name:e("Read the error","Leia o erro","读懂报错"),intro:e("Errors are a map, not a scolding. Floor job: name the usual ones so you know where to look first — the line, the name, the type.","Erro é mapa, não bronca. Trabalho deste andar: nomear os comuns pra saber onde olhar primeiro — a linha, o nome, o tipo.","报错是地图，不是骂人。这层的工作：叫出常见错误，好知道先看哪——行号、名字、类型。"),quest:e("Trigger one intentional error in a tiny script, read the message out loud, then fix it.","Force um erro de propósito num scriptzinho, leia a mensagem em voz alta e conserte.","在小脚本里故意弄出一个错，大声读报错，再修好。"),pack:{id:"code-errors",items:v([["SyntaxError","SyntaxError","SyntaxError","The code is not valid language — a missing ) or :","O código não é linguagem válida — faltou ) ou :","代码不合语法——少了 ) 或 :","Fix the shape first. The computer never guesses your meaning.","Conserte a forma primeiro. O computador não adivinha sua intenção.","先改形状。电脑不会猜你的意思。"],["NameError","NameError","NameError","You used a name that was never defined","Você usou um nome que nunca foi definido","用了从未定义的名字","Typos and forgotten imports are the usual suspects.","Erro de digitação e import esquecido são os suspeitos.","拼写错和忘了 import 最常见。"],["TypeError","TypeError","TypeError","An operation does not fit that kind of value","Uma operação não cabe naquele tipo de valor","这个操作套不到这种值上",'"None has no attribute…" usually means you called something on a missing result.','"None has no attribute…" costuma ser chamar método em resultado ausente.',"None has no attribute… 多半是对空结果调用了方法。"],["IndexError","IndexError","IndexError","You asked for a list slot that does not exist","Pediu um lugar da lista que não existe","访问了列表里不存在的位置","Off-by-one: the last index is length − 1.","Off-by-one: o último índice é length − 1.","差一：最后一个下标是 length − 1。"],["KeyError","KeyError","KeyError","That dictionary key is not there","Aquela chave do dicionário não está lá","字典里没有这个键",'.get(key) or "key in dict" before you assume.','.get(key) ou "key in dict" antes de assumir.',"先 .get(key) 或 key in dict，别假设一定有。"],["ValueError","ValueError","ValueError","The type is fine; the value is not usable that way","O tipo está ok; o valor não serve assim","类型对，但这个值不能这么用",'int("hi") is the classic demo.','int("hi") é o demo clássico.','经典例子：int("hi")。'],["ZeroDivisionError","ZeroDivisionError","ZeroDivisionError","You divided by zero","Você dividiu por zero","除以了零","Check the denominator before you trust a ratio.","Cheque o denominador antes de confiar numa razão.","算比例前先看分母。"],["AttributeError","AttributeError","AttributeError","That object has no such method or field","Aquele objeto não tem esse método ou campo","对象没有这个方法或字段","Wrong type in the variable, or a typo in the name.","Tipo errado na variável, ou typo no nome.","变量类型不对，或名字拼错。"],["ImportError","ImportError","ImportError","Python could not load that module","O Python não conseguiu carregar aquele módulo","Python 加载不了那个模块","Wrong name, wrong folder, or the package is not installed.","Nome errado, pasta errada, ou o pacote não está instalado.","名字错、目录错，或包没装。"],["IndentationError","IndentationError","IndentationError","Spaces/tabs do not match what Python expects","Espaços/tabs não batem com o que o Python espera","空格/制表符对不上 Python 的要求","Pick spaces, stay consistent, never mix.","Escolha espaços, seja consistente, nunca misture.","统一用空格，别混用。"],["Stack trace","Stack trace","堆栈跟踪","The call chain that led to the crash","A cadeia de chamadas que levou à quebra","通向崩溃的调用链","Read from the bottom: that is usually your code.","Leia de baixo: costuma ser o seu código.","从下往上看：多半是你的代码。"],["Reproduce first","Reproduza primeiro","先复现","Make the bug happen again on purpose, small","Faça o bug acontecer de novo de propósito, pequeno","故意再让 bug 以小规模出现一次","If you cannot reproduce it, you cannot trust the fix.","Se não reproduz, não dá pra confiar no conserto.","复现不了，就别信修好了。"]])}}],fe={ai:ie,english:de,programming:ge,mandarin:he,handwriting:ce},ve=e("The basics","O básico","基础"),ye=e("Floor 0: useful chunks first — learn the block, say it if it is speech, then prove it from memory. Clear it and the climb hardens.","Andar 0: blocos úteis primeiro — aprenda o bloco, diga em voz alta se for fala, depois prove de memória. Limpe e a subida endurece.","第0层：先有用的整块——学整块，能说就大声说，再凭记忆证明。清关后关卡变难。");function we(a,t,s=Math.random){const r=fe[a.id];if(r)return r;const o=K(a,t,s);return o?[{id:`${a.id}-basics`,name:ve,intro:ye,pack:{...o.pack??{id:a.id},items:o.items}}]:[]}function Pe(a,t,s,r=Math.random){const o=[];for(const m of new Set(a)){const u=Q(m);if(!u)continue;const d=we(u,t.filter(h=>h.skillId===m),r);d.length&&o.push({skill:u,tiers:d})}return g(o,r).sort((m,u)=>G(s,m.skill.id).plays-G(s,u.skill.id).plays)}export{E as S,Ae as a,ze as b,xe as c,B as d,Ie as e,qe as l,Pe as p,Te as r,$ as s,we as t};
